    // ══════════════════════════════════════════════════════════════════
    // DrawImageAnimTex — clone de DrawImage para texturas animadas (webp)
    // referenciadas via função extra ($GIF, FUNC_ANIM_TEX em
    // ExtrasReader), SEM passar pelo cnv.
    //
    // Mesma lógica de blend mode / alpha / flip / zoom / rotação / offsets
    // de sprite que DrawImage já tem — a ÚNICA diferença de fundo é a
    // ORIGEM de imageWidth/imageHeight/textureId (getAnimTex(animTexIndex)
    // em vez de cnv[frameIndex] + getImage(imageId)) e a ausência de
    // recorte de sprite sheet (a textura é usada INTEIRA: u=0, v=0,
    // uSize/vSize cobrem 100% dela, ajustado por folderScale igual ao
    // original — não existe cnvSrcX/cnvSrcY/offsetCnvX/offsetCnvY aqui
    // porque não há cnv).
    // ══════════════════════════════════════════════════════════════════
    private void DrawImageAnimTex(GlobalWork gw, ObjReq objreq, int animTexIndex,
            int drawPosX, int drawPosY, int flipFlags,
            int offsetSrcX, int offsetSrcY, int baseSrcX, int baseSrcY,
            int ignoredFlags, int zoomXPercent, int zoomYPercent) {

        AnimatedTexture tex = this.ChrGameData[objreq.acttype].getAnimTex(animTexIndex);
        if (tex == null) {
            return;
        }

        int imageWidth = tex.GetWidth();
        int imageHeight = tex.GetHeight();

        if (imageWidth > 0 && imageHeight > 0) {

            int srcWidth = imageWidth + objreq.iOffsetSprXSize;
            int srcHeight = imageHeight + objreq.iOffsetSprYSize;

            float folderScale = (objreq.acttype == 3 || objreq.acttype == 4) ? 2.0f : 1.0f;

            float scaleX = zoomXPercent / 100.0f;
            float scaleY = zoomYPercent / 100.0f;

            // Alpha real (mesma fórmula de DrawImage)
            int computedAlpha = objreq.iAlpha + objreq.iGlobalAlpha;
            int clampedAlpha = Math.max(0, Math.min(255, computedAlpha));

            int textureId = tex.GetImage();

            if (textureId != 0) {

                // -------------------------------------
                // Decisão de modo/color baseado no alpha — IDÊNTICO a DrawImage
                // -------------------------------------
                if (clampedAlpha == 0 && (objreq.wActFlag & 2048) == 0) {
                    Graphics2D.getInstance().drawMode(gw.gl, 3);
                    Graphics2D.getInstance().setColorGl(gw.gl, 255, 255, 255, 255);
                } else if ((objreq.wActFlag & 512) == 0 && (objreq.wObjFlag & 512) == 0) {

                    if ((objreq.wActFlag & 1024) == 0 && (objreq.wObjFlag & 1024) == 0) {
                        Graphics2D.getInstance().drawMode(gw.gl, (clampedAlpha == 255) ? 3 : 0);
                        Graphics2D.getInstance().setColorGl(gw.gl, 255, 255, 255, clampedAlpha);
                    } else {
                        Graphics2D.getInstance().setColorGl(gw.gl, 255, 255, 255, 255);
                        Graphics2D.getInstance().drawMode(gw.gl, 2);
                    }

                } else {
                    Graphics2D.getInstance().setColorGl(gw.gl, 255, 255, 255, clampedAlpha);
                    Graphics2D.getInstance().drawMode(gw.gl, 1);
                }

                // -------------------------------------
                // Cálculo de posição / flips — IDÊNTICO a DrawImage
                // -------------------------------------
                int drawX = drawPosX;
                int drawY = drawPosY;
                int drawFlags = 0;

                if ((flipFlags & 16) != 0) { // flip horizontal
                    drawX = drawPosX - (srcWidth * zoomXPercent / 100);
                    drawFlags |= 1;
                }

                if ((flipFlags & 32) != 0) { // flip vertical
                    drawY = drawPosY - (srcHeight * zoomYPercent / 100);
                    drawFlags |= 2;
                }

                int srcX = baseSrcX + offsetSrcX;
                int srcY = baseSrcY + offsetSrcY;

                // Sem cnv: sem recorte de sprite sheet — textura inteira.
                float u = 0f;
                float v = 0f;
                float uSize = srcWidth * folderScale / imageWidth;
                float vSize = srcHeight * folderScale / imageHeight;

                // Desenho final
                Graphics2D.getInstance().drawTexture(gw.gl, textureId, drawX, drawY, srcX, srcY, srcWidth, srcHeight, u, v, uSize, vSize, drawFlags, objreq.iRotate, scaleX, scaleY);

                bDrawPiece = true;
            }
        }
    }

