    public void GLContextRecreated(GlobalWork gw) {
    // 1) Zera os IDs herdados do contexto morto SEM chamar glDeleteTextures
    //    (deletar aqui apagaria objetos do contexto novo que reusaram o ID).
    AndroidGLTexture.invalidateAll();

    // 2) Texturas de string: além de zerar o ID, é preciso resetar
    //    bFirstFlash para que flash() recrie a textura via glGenTextures
    //    em vez de tentar texSubImage2D num ID inválido.
    if (this.stringTexture != null) {
        if (this.stringTexture[0] != null) this.stringTexture[0].invalidateGL();
        if (this.stringTexture[1] != null) this.stringTexture[1].invalidateGL();
    }

    // 3) FBO offscreen: marca para recriar framebuffer + textura no próximo
    //    bind() (um FBO com nome velho ficaria incompleto e descartaria todo
    //    o desenho da cena → tela preta).
    if (this.osb != null) this.osb.invalidateGL();

    // 4) Recarrega os PNGs de todos os .pac vivos de volta NOS MESMOS
    //    objetos AndroidGLTexture (índices preservados). loadingImage se
    //    recarrega sozinho no DrawExec (checagem GetImage() == 0).
    //    Obs.: imageTexture (imagem baixada por DL) fica com ID 0 até o
    //    jogo redesenhá-la pelo fluxo normal de download.
    GameData.GLReloadAll(gw);
}

   
   public byte[] GetVideoData(int acttype, int videoIndex) {
    int idx = acttype & 0x1F;
    
    if (idx < 0 || idx >= this.ChrGameData.length) return null;
    GameData gd = this.ChrGameData[idx];
    if (gd == null || gd.vid == null || videoIndex < 0 || videoIndex >= gd.vid.length) return null;
    return gd.vid[videoIndex];
}

public int GetVideoThumbTexId(int acttype, int videoIndex) {
    int idx = acttype & 0x1F;
    if (idx < 0 || idx >= this.ChrGameData.length) return 0;
    GameData gd = this.ChrGameData[idx];
    if (gd == null) return 0;
    return gd.getVideoThumbTexId(videoIndex);
}

