private void processInput(GlobalWork gw) {
    this.PlaySE(gw, 0);
    // EDITOR: com o jogo pausado pelo editor os toques nao viram comando de luta
    if (!EditMode.blockGameInput()) {
        this.controller.SetKey(gw.keyData);
    }
    
    TapXPos[0] = this.controller.GetTapX();
    TapYPos[0] = this.controller.GetTapY();
    TapPullXPos[0] = this.controller.GetTapPullX();
    TapPullYPos[0] = this.controller.GetTapPullY();
    TapType[0] = this.controller.GetTapType();

    iTouchStatus = 0;
    for (int i = 0; i < 5; i++) {
        TouchesStatus[i] = 0;
        TouchesXPos[i] = gw.keyData.getX(i);
        TouchesYPos[i] = gw.keyData.getY(i);
        
        TouchesXPosGame[i] = TouchesXPos[i] - _screenoffect_frame[0];
        TouchesYPosGame[i] = TouchesYPos[i] + _screenoffect_frame[1];

        if (gw.keyData.isBeginTouch(i)) {
            TouchesStatus[i] = 1;
            iTouchStatus = 1;
        }
    }
    gw.keyData.ClearBegin();
    bBackKeyPush = gw.bBackKey;
    gw.bBackKey = false;
}

private void resetTouches() {
    for (int i = 0; i < 5; i++) {
        TouchesStatus[i] = 0;
        TouchesXPos[i] = 0;
        TouchesYPos[i] = 0;
        TouchesXPosGame[i] = 0;
        TouchesYPosGame[i] = 0;
    }
}

private void executeTaskChain(GlobalWork gw) {
    tcbNow = tcbHead.next;
    tcbPrev = tcbHead;

    while (tcbNow != null) {
        if (bTaskSkip && (tcbNow.prio & 0xFF00) != 4096) break;

        boolean isSleeping = (iTaskSleep != 0 || bActionStop);
        boolean canExecute = !isSleeping || (tcbNow.prio & 0xF000) == 12288;

        if (!tcbNow.act) {
            // Remove task inativa
            tcbPrev.next = tcbNow.next;
            tcbNow.next = tcbStock;
            tcbStock = tcbNow;
            tcbNow = tcbPrev.next;
            continue;
        }

        if (canExecute && tcbNow.skip == 0 && tcbNow.md != 0) {
            objExec = tcbNow.obj;
            this.Game(gw, tcbNow.md);
        }

        tcbPrev = tcbNow;
        tcbNow = tcbNow.next;
    }
}

private void handleResume(GlobalWork gw) {
    if (this.stringTexture == null) {
        this.stringTexture = new StringTexture[]{ new StringTexture(), new StringTexture() };
    }

    // ─────────────────────────────────────────────────────────────────────
    // BUGFIX (tela preta no boot + texturas sumindo ao voltar do recentes):
    //
    //   Graphics2D.getInstance().dispose();   ← REMOVIDO
    //   Graphics2D.getInstance().Init();      ← REMOVIDO
    //
    // No ES 1.0 original, dispose()/Init() só recriava buffers Java e era
    // inofensivo. No port ES 2.0, dispose() DELETA O PROGRAMA DE SHADER e
    // zera todos os handles (attrib/uniform = -1), e Init() NÃO os recria
    // (isso é papel do InitGL, que só roda em onSurfaceChanged).
    //
    // Como AndroidGLView.onResume() liga gw.bResume a cada retomada, este
    // método rodava no 1º frame após todo InitGL e matava o pipeline recém-
    // criado: no boot → tela preta (girar a tela dispara onSurfaceChanged →
    // InitGL de novo, já com bResume consumido → imagem aparece); ao voltar
    // do recentes → flash() passa a usar handles -1, os ponteiros de
    // atributo ficam presos em buffers órfãos do instance antigo e a cada
    // ciclo mais sprites são desenhados com geometria inválida ("somem"),
    // até a tela ficar preta.
    //
    // O pipeline GL agora é gerenciado exclusivamente por InitGL
    // (AndroidGLRender.InitScreen) e pela recarga em GLContextRecreated().
    // ─────────────────────────────────────────────────────────────────────

    // Restaura o comportamento original: o flag ESTÁTICO avisa as tasks do
    // jogo (recriação de gamepads no case 1117, CreateGamepad etc.) que
    // houve retomada. Ele é limpo automaticamente no loop do Run().
    bResume = true;

    this.PlayBGM(gw, iPlayBGMNo, bBGMPlayLoop);
    gw.bResume = false;
}

