    public void StartPlayerAttack(GlobalWork gw) {
        int playerno = tcbNow._work[0];
        int cpupno = 1 - playerno;
        TCB tcbDePlayer = tcbPlayer[playerno];
        tcbDePlayer.wFlag &= -4098;
        if (CancelTime[playerno] > 0) {
            tcbDePlayer = tcbPlayer[cpupno];
            tcbDePlayer.iHitStop *= 2;
            tcbNow.iHitStop = 0;
        }

        if (PlayerXPos[playerno] != PlayerXPos[cpupno]) {
            ObjReq obj;
            if (PlayerXPos[playerno] < PlayerXPos[cpupno]) {
                obj = objExec;
                obj.wObjFlag &= -17;
            } else {
                obj = objExec;
                obj.wObjFlag |= 16;
            }
        }

        this._SetObj(gw, playerno * 4 + 150);
        PlayerAttack[playerno] = 1;
        PlayerHitStop[playerno] = 10;
        DamageHitBack[playerno] = 0;
        GuardHitBack[playerno] = 13;
        CancelTime[playerno] = 0;
        DamageHitActNo[1 - playerno] = 0;
        PlayerSearch[playerno] = false;
        SpecialBulletNumber[playerno] = 0;
        tcbNow.iHitStop = 0;
        int golpeno = SpecialType[playerno];
        SpecialKind[playerno] = (short) (this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + 0 + 1] << 8 & '\uff00' | this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + 0]);
        short anoinicial = (short) (this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + 2 + 1] << 8 & '\uff00' | this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + 2]);
        // EDITOR: numero do golpe (aba GOLPE), contador T+n e auto-pausa
        if (isTreino()) {
            EditMode.onGolpe(playerno, golpeno, anoinicial, tcbNow.md);
        }
        if (SpecialType[playerno] == 14 || SpecialType[playerno] == 15) {
            AngryOn[playerno] = true;
        }

        if (objExec.ano >= 40 && objExec.ano != 89 && objExec.ano != 80 && objExec.ano < 93 && anoinicial >= 40 && (SpecialType[playerno] < 9 || SpecialType[playerno] > 12)) {
            tcbDePlayer = this._TaskMake(gw, 965, 13598);
            tcbDePlayer._work[0] = 8;
            tcbDePlayer._work[3] = PlayerXPos[playerno];
            tcbDePlayer._work[4] = PlayerYPos[playerno];
            tcbDePlayer._work[5] = 0;
        }

        objExec.ano = 0;
        this._SetAct(gw, objExec.acttype, anoinicial);
        byte golpewithdistcalc;
        if (PlayerYPos[playerno] >= PlayerYPos[cpupno] + 3342336) {
            golpewithdistcalc = 17;
        } else if (PlayerYPos[playerno] <= PlayerYPos[cpupno] - 2424832) {
            golpewithdistcalc = 18;
        } else {
            golpewithdistcalc = 2;
        }

        BulletAction[playerno][0] = (short) (this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + golpewithdistcalc * 2 + 1] << 8 & '\uff00' | this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + golpewithdistcalc * 2]);
        BulletAction[playerno][1] = (short) (this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + 6 + 1] << 8 & '\uff00' | this.ChrGameData[playerno + 3].piGameData[this.ChrGameData[playerno + 3].piGameDataPos[4] + golpeno * 2 * this.ChrGameData[playerno + 3].piGameDataXSize[4] + 6]);
    }

