    void _ActReqMain(GlobalWork global, ObjReq obj) {
    // 1. Verificações de segurança
    if (obj == null || (obj.acttype & 1044480) != 0) return;

    // Se o ponteiro de dados for nulo, a animação é considerada encerrada
    if (obj.apt == 0) {
        obj.wActFlag |= 2; // Flag de Fim de Animação
        return;
    }

    int acttype = obj.acttype & -1044481;

    // 2. Sincronização com o Pai (Hierarchy Sync)
    // 0xA000 é a combinação das flags de sincronização de posição e frame
    if (obj.parent != null && (obj.wActFlag & 0xA000) != 0) {
        if ((obj.wActFlag & 0x8000) != 0) { // Sincronizar Frame (PAT)
            if (obj.pat != obj.parent.pat) {
                obj.pat = obj.parent.pat;
                obj.time = 0;
                obj.wActFlag &= -3; // Reseta estados de término
            } else {
                obj.time = -1; // Trava o tempo se já estiver sincronizado
            }
        }
        // Segue a posição X/Y do objeto pai
        obj.x = obj.parent.x;
        obj.y = obj.parent.y;
    }

    // 3. Controle de Fluxo e Pausa
    if (obj.pat >= obj.mpt) {
        obj.wActFlag |= 2;
    } else if ((obj.wActFlag & 2) == 0) {
        // Verifica se o sistema global ou o objeto está pausado (Flag 4)
        if (obj.parent != null) {
            if ((obj.parent.wActFlag & 4) != 0) return;
        } else if ((obj.wActFlag & 4) != 0) {
            return;
        }

        // 4. Física e Interpolação de Frame
        if (obj.time > 0) {
            // Se OptData[2] estiver ativo, processa interpolações suaves (Hokan automático)
            if (obj.OptData[2] != 0) {
                obj.iRotate += obj.iRotateAdd;
                obj.iAlpha += obj.iAlphaAdd;
                obj.zoomxBase += obj.iXZoomAdd;
                obj.zoomyBase += obj.iYZoomAdd;
                obj.iXZoom = obj.zoomxBase / 128;
                obj.iYZoom = obj.zoomyBase / 128;
                obj.oxBase += obj.oxAdd;
                obj.oyBase += obj.oyAdd;
                obj.ox = obj.oxBase / 128;
                obj.oy = obj.oyBase / 128;
            }

            // Movimentação Física (X e Y)
            if ((obj.wActFlag & 0xA000) == 0) {
                boolean isFlippedX = (obj.wObjFlag & 16) != 0;
                boolean isFlippedY = (obj.wObjFlag & 32) != 0;

                if (obj.iXSpeed != 0) {
                    obj.x += isFlippedX ? -obj.iXSpeed : obj.iXSpeed;
                }
                if (obj.iYSpeed != 0) {
                    obj.y += isFlippedY ? -obj.iYSpeed : obj.iYSpeed;
                }

                // Aplica aceleração à velocidade
                obj.iXSpeed += obj.iXAccel;
                obj.iYSpeed += obj.iYAccel;
            }

            // Decrementa o tempo do frame
            obj.time--;
            if (obj.time > 0) return;

            // Avança para o próximo frame (PAT)
            if ((obj.wActFlag & 1) != 0) {
                obj.pat = 0; // Loop
            } else {
                obj.pat++;
                if (obj.pat >= obj.mpt) {
                    obj.wActFlag |= 2;
                    return;
                }
            }
        }

        // 5. Parsing do Próximo Frame (Leitura Binária do DAC)
        byte[] dac = this.ChrGameData[acttype].getData(3);
        int frameRefPtr = obj.apt + (obj.pat << 1);
        int dataPtr = ((dac[frameRefPtr + 1] & 255) << 8 | dac[frameRefPtr] & 255) + obj.apt + (obj.mpt << 1);

        byte flagsByte = dac[dataPtr++];

        // Tempo do Frame (Flag 32)
        if ((flagsByte & 32) != 0) {
            obj.time = dac[dataPtr++] & 255;
            obj.timeMax = obj.time;
        } else {
            obj.time = 0;
            obj.timeMax = 0;
        }

        // ID da Imagem (2 bytes LE)
        obj.img = (short) ((dac[dataPtr + 1] & 255) << 8 | dac[dataPtr] & 255);
        dataPtr += 2;

        // Ponto de Origem / Offset (Flag 1)
        if ((flagsByte & 1) != 0) {
            obj.ox = (short) ((dac[dataPtr + 1] & 255) << 8 | dac[dataPtr] & 255);
            dataPtr += 2;
            obj.oy = (short) ((dac[dataPtr + 1] & 255) << 8 | dac[dataPtr] & 255);
            dataPtr += 2;
        } else {
            obj.ox = 0;
            obj.oy = 0;
        }

        // Flags de Ação (Flag 2)
        obj.wActFlag &= 40960;
        if ((flagsByte & 2) != 0) {
            obj.wActFlag |= (short) ((dac[dataPtr + 1] & 255) << 8 | dac[dataPtr] & 255);
            dataPtr += 2;
        }

        // Som (SE - Flag 8)
        obj.se = -1;
        if ((flagsByte & 8) != 0) {
            byte seId = dac[dataPtr++];
            if (seId < 80) {
                this.PushSE(global, seId - 1);
            } else {
                obj.se = seId;
            }
        }

        // Reset de Física
        if ((obj.wActFlag & 64) == 0) {
            obj.iXSpeed = 0;
            obj.iYSpeed = 0;
        }
        obj.iXAccel = 0;
        obj.iYAccel = 0;

        // Movimento / Física detalhada (Flag 4)
        if ((flagsByte & 4) != 0) {
            byte mvFlags = dac[dataPtr++];
            if ((mvFlags & 1) != 0) {
                obj.iXSpeed = readIntLE(dac, dataPtr);
                dataPtr += 4;
            }
            if ((mvFlags & 2) != 0) {
                obj.iYSpeed = readIntLE(dac, dataPtr);
                dataPtr += 4;
            }
            if ((mvFlags & 4) != 0) {
                obj.iXAccel = readIntLE(dac, dataPtr);
                dataPtr += 4;
            }
            if ((mvFlags & 8) != 0) {
                obj.iYAccel = readIntLE(dac, dataPtr);
                dataPtr += 4;
            }
        }

        // Colisões / Hitbox (Flag 16)
        int hitMask = 0;
        if ((flagsByte & 16) != 0) {
            obj.iHitNum = dac[dataPtr++] & 255;
            for (int i = 0; i < obj.iHitNum; i++) {
                byte hFlag = dac[dataPtr++];
                int base = i * 5;
                obj.hit[base] = hFlag & 127;
                hitMask |= 1 << (hFlag & 127);

                if ((hFlag & 128) != 0) { // Coordenadas 16-bit
                    for (int k = 1; k <= 4; k++) {
                        obj.hit[base + k] = (short) ((dac[dataPtr + 1] & 255) << 8 | dac[dataPtr] & 255);
                        dataPtr += 2;
                    }
                } else { // Coordenadas 8-bit
                    obj.hit[base + 1] = dac[dataPtr++];
                    obj.hit[base + 2] = dac[dataPtr++];
                    obj.hit[base + 3] = dac[dataPtr++] & 255;
                    obj.hit[base + 4] = dac[dataPtr++] & 255;
                }
            }
        } else {
            obj.iHitNum = 0;
        }

        // Atualiza flags de hit globais se for o objeto principal
        if (obj.parent == null) {
            tcbNow.iHitCount = (obj.iHitNum > 0) ? 1 : 0;
            tcbNow.iHitFlag = hitMask;
        }

        // 6. Opções Adicionais e Comandos Customizados (Flag 64)
        // ══════════════════════════════════════════════════════════════
        // NOVO: delega inteiramente para ExtrasReader a decisão de "isto é
        // um gatilho de funções extras (225) ou uma OPT normal?". Este
        // método não conhece funcCount, códigos de função, nem 225 —
        // apenas pergunta e, se for extras, entrega o controle total
        // (dac/dataPtr/obj) para ExtrasReader.handle(...) continuar o
        // parsing e devolver o dataPtr já avançado.
        //
        // Se um dia as funções extras forem descontinuadas, o único ajuste
        // necessário é ExtrasReader.isExtrasFlag(...) sempre devolver
        // false — nenhuma mudança neste método é necessária.
        // ══════════════════════════════════════════════════════════════
        if ((flagsByte & 64) != 0) {
            int rawOptFlag = (dac[dataPtr + 1] & 255) << 8 | (dac[dataPtr] & 255);
            dataPtr += 2;
            
            if (ExtrasReader.isExtrasFlag(rawOptFlag)) {
            
                obj.wOptFlag = 0;
                obj.OptData[0] = 0;
                obj.OptData[1] = 0;
                obj.OptData[2] = 0;
                obj.OptData[3] = 0;

                try {
                    dataPtr = ExtrasReader.handle(global, obj, this, dac, dataPtr);
                } catch (Throwable t) {
                    Logue.StackTrace(t);
                }

            } else {
                // --- CASO PADRÃO (Flag 64 ativa, não é extras) — INALTERADO ---
                obj.wOptFlag = (short) rawOptFlag;
                for (int i = 0; i < 4; i++) {
                    obj.OptData[i] = dac[dataPtr++] & 255;
                }
            }
        } else {
            // --- CASO SEM FLAG 64 --- (inalterado)
            obj.wOptFlag = 0;
            for (int i = 0; i < 4; i++) {
                obj.OptData[i] = 0;
            }
        }

        // Rotação, Alpha e Zoom (RAZ - Flag 128)
        if ((flagsByte & 128) != 0) {
            obj.iRotate = (short) ((dac[dataPtr + 1] & 255) << 8 | dac[dataPtr] & 255);
            obj.iAlpha = (short) ((dac[dataPtr + 3] & 255) << 8 | dac[dataPtr + 2] & 255);
            obj.iXZoom = (short) ((dac[dataPtr + 5] & 255) << 8 | dac[dataPtr + 4] & 255);
            obj.iYZoom = (short) ((dac[dataPtr + 7] & 255) << 8 | dac[dataPtr + 6] & 255);
            obj.wActFlag |= 2048; // Habilita transformações

            // Processamento do canal Alpha e Blending
            if (obj.iAlpha != 0) {
                int blendMode = obj.iAlpha >> 8;
                obj.iAlpha = 255 - (obj.iAlpha & 255);
                if (blendMode != 0) {
                    if (blendMode == 1) obj.wActFlag |= 512; // Aditivo
                    else obj.wActFlag |= 1024; // Subtrativo/Outro
                }
            } else {
                obj.iAlpha = 255; // Normal por padrão
            }
        } else {
            obj.iAlpha = 255;
            obj.iRotate = 0;
            obj.iXZoom = 100;
            obj.iYZoom = 100;
        }

        // EDITOR: mudancas ao vivo do basico (treino e botao ANOs) valem toda vez que o frame e lido
        EditMode.onFrameParsed(this, obj);

        // Finaliza o processamento do frame (Interpolação de valores)
        this._Hokan(global, obj, flagsByte);
    }
}

