    /** Modo treinamento (iPlayMode 2). */
    static boolean isTreino() {
        return iPlayMode == 2;
    }

    /**
     * Regras de vida do treino (vida nao zera, volta cheia no fim do golpe/dano e a barra de dano parte da
     * vida cheia): so com o botao Stats ligado no editor. Com Stats desligado (o padrao) a vida cai de
     * verdade, a barra parte da vida atual e o KO acontece (o editor reinicia a partida depois).
     */
    static boolean treinoVidaInfinita() {
        return isTreino() && (!EditMode.active || EditMode.statLife);
    }

    /**
     * EDITOR: desenha as caixas do frame atual (obj.hit) com a MESMA conta do CheckObjHit,
     * entao o que aparece e exatamente o que a colisao usa.
     * Azul = hurtbox (1), vermelho = hitbox (2), verde = cura (34), amarelo = outras flags (so com "Outras caixas").
     */
    void editDrawBoxes(GlobalWork gw, ObjReq obj) {
        Graphics2D g2 = Graphics2D.getInstance();
        int flip = obj.wActFlag & 48 ^ obj.wObjFlag & 48;
        int baseX = obj.x >> 16;
        int baseY = obj.y >> 16;
        g2.drawMode(gw.gl, 0);

        for (int i = 0; i < obj.iHitNum; ++i) {
            int flag = obj.hit[i * 5 + 0];
            if (flag < 0) {
                continue;
            }

            int cr;
            int cg;
            int cb;
            if (flag == 1) {
                cr = 40; cg = 140; cb = 255;
            } else if (flag == 2) {
                cr = 255; cg = 40; cb = 40;
            } else if (flag == 34) {
                cr = 40; cg = 255; cb = 90;
            } else {
                if (!EditMode.showOtherBoxes) {
                    continue;
                }
                cr = 255; cg = 210; cb = 0;
            }

            int w = obj.hit[i * 5 + 3];
            int h = obj.hit[i * 5 + 4];
            if (w <= 0 || h <= 0) {
                continue;
            }

            int left = (flip & 16) != 0 ? baseX - obj.hit[i * 5 + 1] - w : baseX + obj.hit[i * 5 + 1];
            int top = (flip & 32) != 0 ? baseY - obj.hit[i * 5 + 2] - h : baseY + obj.hit[i * 5 + 2];
            int x = left + gw.iScreenDrawOffsetX;
            int y = top + gw.iScreenDrawOffsetY;

            g2.setColor(gw.gl, cr, cg, cb, 60);
            g2.drawFillRect(gw.gl, x, y, w, h);
            g2.setColor(gw.gl, cr, cg, cb, 255);
            g2.drawFillRect(gw.gl, x, y, w, 1);
            g2.drawFillRect(gw.gl, x, y + h - 1, w, 1);
            g2.drawFillRect(gw.gl, x, y, 1, h);
            g2.drawFillRect(gw.gl, x + w - 1, y, 1, h);
        }

        g2.setColor(gw.gl, 255, 255, 255, 255);
    }

