        static android.app.Activity findActivityCtx(Object c) {
            for (int i = 0; i < 10 && c != null; ++i) {
                if (c instanceof android.app.Activity) {
                    return (android.app.Activity) c;
                }
                if (c instanceof android.content.ContextWrapper) {
                    c = ((android.content.ContextWrapper) c).getBaseContext();
                } else {
                    break;
                }
            }
            return null;
        }

        static android.app.Activity findActivity(GlobalWork gw) {
            android.app.Activity a = findActivityCtx(gw.context);
            if (a == null) {
                Object gv = gw.glview;
                if (gv instanceof android.view.View) {
                    a = findActivityCtx(((android.view.View) gv).getContext());
                }
            }
            return a;
        }

        static android.app.Activity act() {
            return root == null ? null : findActivityCtx(root.getContext());
        }

        /** Cria a barra (a primeira vez) e mostra. */
        static void setUiVisible(GlobalWork gw, final boolean show) {
            if (ui == null) {
                ui = new android.os.Handler(android.os.Looper.getMainLooper());
            }
            final android.app.Activity a = (show && root == null) ? findActivity(gw) : null;
            if (show && root == null && a == null) {
                android.util.Log.w(TAG, "nao achei a Activity: o editor nao vai aparecer (tenta de novo)");
                return;
            }
            ui.post(new Runnable() {
                public void run() {
                    try {
                        if (show && root == null && a != null) {
                            build(a);
                        }
                        if (root != null) {
                            closePanelNow();
                            barHiddenByPause = false;
                            root.setVisibility(show ? android.view.View.VISIBLE : android.view.View.GONE);
                        }
                        refreshBar();
                        refreshLabels();
                    } catch (Throwable e) {
                        android.util.Log.e(TAG, "erro no editor", e);
                    }
                }
            });
        }

        /** Entrou/saiu da luta do treino: painel fechado, o EDITOR aparece/some da barra. */
        static void postActiveChanged() {
            if (ui == null) {
                return;
            }
            ui.post(new Runnable() {
                public void run() {
                    if (root == null) {
                        return;
                    }
                    closePanelNow();
                    refreshBar();
                    refreshLabels();
                }
            });
        }

        /** Menu de pausa do jogo abriu/fechou: no menu de pausa a barra fica so com o ANOs (sem ⟳ e sem EDITOR). */
        static void postShowBar(final boolean show) {
            if (ui == null) {
                return;
            }
            ui.post(new Runnable() {
                public void run() {
                    if (root == null) {
                        return;
                    }
                    barHiddenByPause = false;
                    if (!show && panelOpen && !globalMode) {
                        closePanelNow();         // o editor do treino nao fica aberto no menu de pausa
                    }
                    root.setVisibility(android.view.View.VISIBLE);
                    refreshBar();
                }
            });
        }

        static float dp() {
            return root.getResources().getDisplayMetrics().density;
        }

        /** Abre o painel: pausa o jogo e encosta a barra no topo. */
        static void openPanel(boolean open) {
            if (root == null) {
                return;
            }
            if (!open) {
                requestClose(null);
                return;
            }
            android.widget.FrameLayout.LayoutParams lp = (android.widget.FrameLayout.LayoutParams) root.getLayoutParams();
            android.view.View parent = (android.view.View) root.getParent();
            int pw = parent == null ? 0 : parent.getWidth();
            float d = dp();
            if (minimized) {
                setMinimized(false);
            }
            if (panel.getVisibility() != android.view.View.VISIBLE) {
                barLeft = lp.leftMargin;
                barTop = lp.topMargin;
            }
            if (tab == TAB_BASIC) {
                tab = TAB_MPT;                   // o editor do treino nao tem mais o basico
            }
            panel.setVisibility(android.view.View.VISIBLE);
            scrim.setVisibility(android.view.View.VISIBLE);
            paused = true;
            panelOpen = true;
            applyPanelLayout();
            loadTab(true);                       // segue o golpe/ANO/MPT atual do jogo
            refreshLabels();
        }

        /**
         * Painel completo: 62% da largura, altura toda, encostado no topo.
         * Aba BASICO: painel compacto, do tamanho do conteudo, onde a barra esta, sem escurecer o jogo.
         */
        static void applyPanelLayout() {
            if (root == null || !panelOpen) {
                return;
            }
            boolean basic = tab == TAB_BASIC || globalMode;
            android.widget.FrameLayout.LayoutParams lp = (android.widget.FrameLayout.LayoutParams) root.getLayoutParams();
            android.view.View parent = (android.view.View) root.getParent();
            int pw = parent == null ? 0 : parent.getWidth();
            float d = dp();
            int w = basic ? (pw > 0 ? Math.min((int) (pw * 0.44f), (int) (330 * d)) : (int) (300 * d))
                    : (pw > 0 ? Math.min((int) (pw * 0.62f), (int) (520 * d)) : (int) (420 * d));
            lp.width = w;
            lp.leftMargin = pw > 0 ? Math.max(0, Math.min(barLeft, pw - w)) : 0;
            lp.topMargin = basic ? Math.max(0, barTop) : 0;
            lp.height = basic ? android.view.ViewGroup.LayoutParams.WRAP_CONTENT
                    : android.view.ViewGroup.LayoutParams.MATCH_PARENT;   // acompanha a tela (inclusive com teclado)
            root.setLayoutParams(lp);

            android.widget.LinearLayout.LayoutParams pl = (android.widget.LinearLayout.LayoutParams) panel.getLayoutParams();
            pl.height = basic ? android.view.ViewGroup.LayoutParams.WRAP_CONTENT : 0;
            pl.weight = basic ? 0 : 1;
            panel.setLayoutParams(pl);
            android.widget.LinearLayout.LayoutParams fl = (android.widget.LinearLayout.LayoutParams) formScroll.getLayoutParams();
            fl.height = basic ? android.view.ViewGroup.LayoutParams.WRAP_CONTENT : 0;
            fl.weight = basic ? 0 : 1;
            formScroll.setLayoutParams(fl);

            fullBox.setVisibility(basic ? android.view.View.GONE : android.view.View.VISIBLE);
            actionsBox.setVisibility(basic ? android.view.View.GONE : android.view.View.VISIBLE);
            editor.setVisibility(basic ? android.view.View.GONE : android.view.View.VISIBLE);
            formScroll.setVisibility(basic ? android.view.View.VISIBLE : android.view.View.GONE);
            panel.setBackgroundColor(basic ? 0xE6101319 : 0xF0101319);
            scrim.setBackgroundColor(basic ? 0x00000000 : 0x33000000);
            root.post(new Runnable() {
                public void run() {
                    clampRoot();
                }
            });
        }

        /** Fecha o painel sem perguntar (o jogo continua). */
        static void closePanelNow() {
            if (root == null) {
                return;
            }
            hideKeyboard();
            android.widget.FrameLayout.LayoutParams lp = (android.widget.FrameLayout.LayoutParams) root.getLayoutParams();
            panel.setVisibility(android.view.View.GONE);
            scrim.setVisibility(android.view.View.GONE);
            lp.width = android.view.ViewGroup.LayoutParams.WRAP_CONTENT;
            lp.height = android.view.ViewGroup.LayoutParams.WRAP_CONTENT;
            if (barLeft >= 0) {
                lp.leftMargin = barLeft;
                lp.topMargin = barTop;
            }
            root.setLayoutParams(lp);
            gBoxes = false;
            if (globalMode) {
                globalMode = false;              // volta a ser o editor do treino
                globalEdit = false;
                tab = prevTab;
                blockOk = false;
                loadedText = "";
                basicText = "";
                savedJustNow = false;
            }
            paused = false;
            panelOpen = false;
            frameStepRequests.set(0);
            stepRequests.set(0);
            followAfterStep = false;
            root.post(new Runnable() {
                public void run() {
                    clampRoot();
                }
            });
            refreshLabels();
        }

        /** Fechar pelo botao, voltar ou toque fora: pergunta se salva quando ha alteracao. */
        static void requestClose(final Runnable then) {
            if (!panelOpen) {
                if (then != null) {
                    then.run();
                }
                return;
            }
            guard(new Runnable() {
                public void run() {
                    closePanelNow();
                    if (then != null) {
                        then.run();
                    }
                }
            });
        }

        static void setMinimized(boolean m) {
            minimized = m;
            refreshBar();
        }

        /** [ ⟳ | EDITOR | ANOs | − ] (EDITOR so na luta do treino) ou [ + ] minimizada. */
        static void refreshBar() {
            if (root == null || barRestart == null) {
                return;
            }
            boolean m = minimized;
            boolean pm = pauseMenuShown;
            int vis = m ? android.view.View.GONE : android.view.View.VISIBLE;
            int rs = !m && !pm ? android.view.View.VISIBLE : android.view.View.GONE;
            int ed = !m && active && !pm ? android.view.View.VISIBLE : android.view.View.GONE;
            barRestart.setVisibility(rs);
            barDiv1.setVisibility(rs);
            barEditor.setVisibility(ed);
            barDiv2.setVisibility(ed);
            barGlobal.setVisibility(vis);
            barDiv3.setVisibility(vis);
            barMin.setVisibility(vis);
            barPlus.setVisibility(m ? android.view.View.VISIBLE : android.view.View.GONE);
            root.post(new Runnable() {
                public void run() {
                    clampRoot();
                }
            });
        }

        static void clampRoot() {
            if (root == null || !(root.getParent() instanceof android.view.View)) {
                return;
            }
            android.widget.FrameLayout.LayoutParams lp = (android.widget.FrameLayout.LayoutParams) root.getLayoutParams();
            android.view.View parent = (android.view.View) root.getParent();
            int maxL = Math.max(0, parent.getWidth() - root.getWidth());
            int maxT = Math.max(0, parent.getHeight() - root.getHeight());
            int l = Math.max(0, Math.min(lp.leftMargin, maxL));
            int t = Math.max(0, Math.min(lp.topMargin, maxT));
            if (l != lp.leftMargin || t != lp.topMargin) {
                lp.leftMargin = l;
                lp.topMargin = t;
                root.setLayoutParams(lp);
            }
        }

        static void hideKeyboard() {
            if (root == null) {
                return;
            }
            android.view.View f = root.findFocus();
            if (f != null) {
                android.view.inputmethod.InputMethodManager imm = (android.view.inputmethod.InputMethodManager)
                        root.getContext().getSystemService(android.content.Context.INPUT_METHOD_SERVICE);
                if (imm != null) {
                    imm.hideSoftInputFromWindow(f.getWindowToken(), 0);
                }
                f.clearFocus();
            }
        }

        static void toast(String s) {
            if (root != null) {
                android.widget.Toast.makeText(root.getContext(), s, android.widget.Toast.LENGTH_SHORT).show();
            }
        }

        // ---- alteracoes nao salvas ------------------------------------------------------------

        static String currentText() {
            return tab == TAB_BASIC ? basicText : (editor == null ? "" : editor.getText().toString());
        }

        static boolean isDirty() {
            return panelOpen && blockOk && !currentText().equals(loadedText);
        }

        /** Roda {@code action}; se houver alteracao nao salva, pergunta antes: SALVAR / DESCARTAR / CANCELAR. */
        static void guard(final Runnable action) {
            if (!isDirty()) {
                action.run();
                return;
            }
            android.app.Activity a = act();
            if (a == null) {
                action.run();
                return;
            }
            android.app.AlertDialog.Builder b = new android.app.AlertDialog.Builder(a);
            b.setTitle("Salvar alteracoes?");
            b.setMessage("O bloco $" + blockKey(tab, edGolpe, edAno, edPat) + " foi alterado e ainda nao foi salvo.");
            b.setPositiveButton("SALVAR", new android.content.DialogInterface.OnClickListener() {
                public void onClick(android.content.DialogInterface d, int w) {
                    if (confirm()) {
                        action.run();
                    }
                }
            });
            b.setNegativeButton("DESCARTAR", new android.content.DialogInterface.OnClickListener() {
                public void onClick(android.content.DialogInterface d, int w) {
                    discard();
                    action.run();
                }
            });
            b.setNeutralButton("CANCELAR", null);
            b.show();
        }

        static void discard() {
            markChanged();
            if (tab == TAB_BASIC) {
                basicText = loadedText;
                publishLive();                   // o jogo volta para o que esta no arquivo
            } else if (editor != null) {
                editor.setText(loadedText);
            }
        }

        // ---- barra [ ⟳ | EDITOR | − ]  /  [ + ] ------------------------------------------

        /** Toque nas partes da barra: toque = acao da parte; arrastar (qualquer parte) = mover a barra. */
        static final android.view.View.OnTouchListener BAR_TOUCH = new android.view.View.OnTouchListener() {
            float downX, downY;
            int startLeft, startTop;
            boolean moved;

            public boolean onTouch(android.view.View v, android.view.MotionEvent ev) {
                switch (ev.getActionMasked()) {
                    case android.view.MotionEvent.ACTION_DOWN:
                        downX = ev.getRawX();
                        downY = ev.getRawY();
                        android.widget.FrameLayout.LayoutParams lp0 = (android.widget.FrameLayout.LayoutParams) root.getLayoutParams();
                        startLeft = lp0.leftMargin;
                        startTop = lp0.topMargin;
                        moved = false;
                        v.setPressed(true);
                        return true;
                    case android.view.MotionEvent.ACTION_MOVE: {
                        float dx = ev.getRawX() - downX;
                        float dy = ev.getRawY() - downY;
                        float slop = 10 * dp();
                        if (!moved && Math.abs(dx) < slop && Math.abs(dy) < slop) {
                            return true;
                        }
                        moved = true;
                        v.setPressed(false);
                        android.widget.FrameLayout.LayoutParams lp = (android.widget.FrameLayout.LayoutParams) root.getLayoutParams();
                        lp.leftMargin = startLeft + (int) dx;
                        lp.topMargin = panelOpen ? 0 : startTop + (int) dy;
                        root.setLayoutParams(lp);
                        clampRoot();
                        barLeft = lp.leftMargin;
                        if (!panelOpen) {
                            barTop = lp.topMargin;
                        }
                        return true;
                    }
                    case android.view.MotionEvent.ACTION_UP:
                        v.setPressed(false);
                        if (!moved) {
                            onBarTap(v);
                        }
                        return true;
                    case android.view.MotionEvent.ACTION_CANCEL:
                        v.setPressed(false);
                        return true;
                    default:
                        return true;
                }
            }
        };

        static void onBarTap(android.view.View v) {
            if (v == barRestart) {
                guard(new Runnable() {
                    public void run() {
                        hideKeyboard();
                        if (globalMode || !active) {
                            closePanelNow();
                            globalRestartRequested = true;
                            toast(active ? "reiniciando a partida..." : "reiniciando (volta ao ultimo carregamento)...");
                        } else {
                            restartRequested = true;
                            toast("reiniciando a partida...");
                        }
                    }
                });
            } else if (v == barEditor) {
                if (panelOpen && !globalMode) {
                    requestClose(null);
                } else if (panelOpen) {
                    requestClose(new Runnable() {
                        public void run() {
                            openPanel(true);
                        }
                    });
                } else {
                    openPanel(true);
                }
            } else if (v == barGlobal) {
                if (panelOpen && globalMode) {
                    requestClose(null);
                } else if (panelOpen) {
                    requestClose(new Runnable() {
                        public void run() {
                            openGlobal();
                        }
                    });
                } else {
                    openGlobal();
                }
            } else if (v == barMin && panelOpen && globalMode) {
                // com o ANOs aberto o − vira "+1F jogo": anda 1 frame do jogo (pergunta antes se ha alteracao)
                guard(new Runnable() {
                    public void run() {
                        requestGameTick();
                    }
                });
            } else if (v == barMin) {
                requestClose(new Runnable() {
                    public void run() {
                        setMinimized(true);
                    }
                });
            } else if (v == barPlus) {
                setMinimized(false);
            }
        }

        // ---- botoes do painel ----------------------------------------------------------------

        static final android.view.View.OnClickListener CLICK = new android.view.View.OnClickListener() {
            public void onClick(android.view.View v) {
                if (v == btnStep1 || v == btnStep10) {
                    stepRequests.addAndGet(v == btnStep1 ? 1 : 10);
                } else if (v == btnFrame1 || v == btnFrame10) {
                    frameStepRequests.addAndGet(v == btnFrame1 ? 1 : 10);
                } else if (v == btnSpeed) {
                    int s = speedDiv;
                    speedDiv = s >= 8 ? 1 : s * 2;
                } else if (v == btnAuto) {
                    autoPause = !autoPause;
                } else if (v == btnStats) {
                    openStatsMenu();
                } else if (v == btnBoxes) {
                    showBoxes = !showBoxes;
                } else if (v == btnSprites || v == btnSounds) {
                    openAssets(v == btnSprites);
                } else if (v == btnPrev || v == btnNext) {
                    final int dd = v == btnPrev ? -1 : 1;
                    guard(new Runnable() {
                        public void run() {
                            navigate(dd);
                        }
                    });
                } else if (v == btnFull) {
                    openFullscreenEditor();
                } else if (v == btnConfirm) {
                    saveOrRestart();
                } else if (v == btnUndo) {
                    undoLast();
                } else if (v == btnReload) {
                    loadTab(false);                  // REDEFINIR: volta ao que esta no arquivo
                    setMsg("redefinido: igual ao arquivo", 0xFF9AA4B4);
                } else {
                    for (int t = 0; t < 4; ++t) {
                        if (v == tabBtn[t] && t != tab) {
                            boolean onScreen = edAno == pubAno[0] && edPat == pubPat[0];
                            if (blockOk && blockTab(t) == blockTab(tab) && (t != TAB_BASIC || onScreen)) {
                                switchKeepingText(t);      // MPT <-> BASICO: mesmo bloco, leva o texto (e as alteracoes)
                                continue;
                            }
                            if (t == TAB_BASIC) {
                                guard(new Runnable() {
                                    public void run() {
                                        tab = TAB_BASIC;
                                        loadTab(true);     // a aba BASICO edita sempre o frame que esta na tela
                                    }
                                });
                                continue;
                            }
                            final int nt = t;
                            guard(new Runnable() {
                                public void run() {
                                    tab = nt;
                                    loadTab(false);
                                }
                            });
                        }
                    }
                }
                refreshLabels();
            }
        };

        /** Stats: caixas de marcar do que e infinito; cada toque ja vale no jogo (applyStats). */
        static void openStatsMenu() {
            android.app.Activity a = act();
            if (a == null) {
                return;
            }
            String[] items = {"Vida infinita (desmarcada = vida normal, KO reinicia)", "Synchro infinito", "Angry infinito (angry ligado)"};
            boolean[] on = {statLife, statSynchro, statAngry};
            android.app.AlertDialog.Builder b = new android.app.AlertDialog.Builder(a);
            b.setTitle("Stats (P1 e P2)");
            b.setMultiChoiceItems(items, on, new android.content.DialogInterface.OnMultiChoiceClickListener() {
                public void onClick(android.content.DialogInterface d, int which, boolean checked) {
                    if (which == 0) {
                        statLife = checked;
                    } else if (which == 1) {
                        statSynchro = checked;
                    } else {
                        statAngry = checked;
                    }
                    int bit = 1 << which;
                    while (true) {
                        int v = statsApply.get();
                        if (statsApply.compareAndSet(v, v | bit)) {
                            break;
                        }
                    }
                    refreshLabels();
                }
            });
            b.setPositiveButton("OK", null);
            b.show();
        }

        /** SPRITES / SONS: as telas do app (pacote com.zue.attackeditor) por cima do jogo pausado. */
        static void openAssets(boolean sprites) {
            String dir = curDir();
            android.app.Activity a = act();
            if (dir == null || a == null) {
                toast("personagem sem pasta");
                return;
            }
            if (isDirty() && !confirm()) {
                return;
            }
            hideKeyboard();
            try {
                if (sprites) {
                    com.zue.attackeditor.GameEditBridge.showSprites(a, new java.io.File(dir), curIsChar());
                } else {
                    com.zue.attackeditor.GameEditBridge.showSounds(a, new java.io.File(dir));
                }
            } catch (Throwable e) {
                android.util.Log.e(TAG, "erro ao abrir " + (sprites ? "sprites" : "sons"), e);
                toast("erro: " + e.getMessage());
            }
        }

        /** Texto do arquivo da aba (ou null). */
        static String fileText(int tabIdx) {
            String dir = curDir();
            if (dir == null) {
                return null;
            }
            try {
                return readText(new java.io.File(fileOf(tabIdx, dir)));
            } catch (java.io.IOException e) {
                return null;
            }
        }

        /**
         * ◀ ▶: so anda para blocos que existem. MPT e GOLPE param no ultimo; ANO pula os que faltam
         * (o DAC pode ter buracos).
         */
        static void navigate(int dd) {
            String text = fileText(tab);
            if (text == null) {
                return;
            }
            if (blockTab(tab) == TAB_ANO) {
                for (int k = 1; k <= 400; ++k) {
                    int na = edAno + dd * k;
                    if (na < 0) {
                        break;
                    }
                    if (locateBlock(text, TAB_ANO, edGolpe, na, 0) != null) {
                        edAno = na;
                        edPat = 0;
                        loadTab(false);
                        return;
                    }
                }
                toast(dd < 0 ? "este e o primeiro ANO" : "este e o ultimo ANO");
                return;
            }
            int ng = edGolpe, np = edPat;
            if (blockTab(tab) == TAB_GOLPE) {
                ng += dd;
            } else {
                np += dd;
            }
            if (ng < 0 || np < 0 || locateBlock(text, tab, ng, edAno, np) == null) {
                toast(dd < 0 ? "este e o primeiro" : (blockTab(tab) == TAB_GOLPE ? "este e o ultimo golpe" : "este e o ultimo MPT do ANO " + edAno));
                return;
            }
            edGolpe = ng;
            edPat = np;
            loadTab(false);
        }

        /** SALVAR grava; logo depois (sem mudar nada) o mesmo botao vira REINICIAR. */
        static void saveOrRestart() {
            if (savedJustNow && !isDirty()) {
                hideKeyboard();
                boolean g = globalMode;
                closePanelNow();
                if (g) {
                    globalRestartRequested = true;
                    toast(active ? "reiniciando a partida..." : "reiniciando (volta ao ultimo carregamento)...");
                } else {
                    restartRequested = true;
                    toast("reiniciando a partida...");
                }
                return;
            }
            if (confirm()) {
                savedJustNow = true;
                refreshSaveButtons();
            }
        }

        static void markChanged() {
            if (savedJustNow) {
                savedJustNow = false;
                refreshSaveButtons();
            }
        }

        static void refreshSaveButtons() {
            if (btnConfirm != null) {
                btnConfirm.setText(savedJustNow ? "REINICIAR" : "SALVAR");
                btnConfirm.setBackgroundColor(savedJustNow ? 0xFF2B3F66 : 0xFF1E5E2E);
            }
            if (compactSave != null) {
                compactSave.setText(savedJustNow ? "REINICIAR" : "APPLY");
                compactSave.setBackgroundColor(savedJustNow ? 0xFF2B3F66 : 0xFF1E8E3E);
            }
        }

        /**
         * Tela cheia para editar o texto da aba (GOLPE/ANO/MPT): gira a tela do jogo para retrato e abre o
         * texto num dialogo de tela inteira. SALVAR grava e volta para paisagem; VOLTAR (ou o voltar do
         * celular) traz o texto para o painel sem gravar e tambem volta para paisagem.
         */
        static void openFullscreenEditor() {
            final android.app.Activity a = act();
            if (a == null || !blockOk || tab == TAB_BASIC) {
                return;
            }
            hideKeyboard();
            final int prevOrientation = a.getRequestedOrientation();
            final float d = dp();
            final android.app.Dialog dlg = new android.app.Dialog(a, android.R.style.Theme_Black_NoTitleBar_Fullscreen);
            android.widget.LinearLayout box = new android.widget.LinearLayout(a);
            box.setOrientation(android.widget.LinearLayout.VERTICAL);
            box.setBackgroundColor(0xFF101319);
            box.setPadding((int) (6 * d), (int) (6 * d), (int) (6 * d), (int) (6 * d));
            android.widget.TextView title = label(a, "$" + blockKey(tab, edGolpe, edAno, edPat) + "  ·  "
                    + new java.io.File(fileOf(tab, curDir())).getName(), 13, 0xFFFFFFFF);
            title.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            title.setPadding((int) (4 * d), (int) (4 * d), 0, (int) (6 * d));
            box.addView(title);
            final android.widget.EditText et = new android.widget.EditText(a);
            et.setTypeface(android.graphics.Typeface.MONOSPACE);
            et.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, 12);
            et.setTextColor(0xFFE6E8EC);
            et.setBackgroundColor(0xFF161A21);
            et.setGravity(android.view.Gravity.TOP | android.view.Gravity.START);
            et.setHorizontallyScrolling(true);
            et.setPadding((int) (8 * d), (int) (8 * d), (int) (8 * d), (int) (8 * d));
            et.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE
                    | android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS | android.text.InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD);
            et.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI | android.view.inputmethod.EditorInfo.IME_FLAG_NO_FULLSCREEN);
            et.setText(editor.getText().toString());
            box.addView(et, new android.widget.LinearLayout.LayoutParams(android.view.ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f));
            final android.widget.TextView msg = label(a, "", 11, 0xFFFF8080);
            msg.setPadding((int) (4 * d), (int) (4 * d), 0, 0);
            box.addView(msg);
            android.widget.LinearLayout r = row(a, box);
            android.widget.Button back = mkButton(a, r, d, "VOLTAR", 1);
            android.widget.Button save = mkButton(a, r, d, "SALVAR", 1.4f);
            save.setBackgroundColor(0xFF1E5E2E);
            dlg.setContentView(box);
            dlg.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);

            final Runnable closeBack = new Runnable() {
                public void run() {
                    editor.setText(et.getText().toString());   // o texto volta para o painel (sem gravar)
                    dlg.dismiss();
                }
            };
            back.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    closeBack.run();
                }
            });
            save.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    editor.setText(et.getText().toString());
                    if (confirm()) {
                        savedJustNow = true;
                        refreshSaveButtons();
                        dlg.dismiss();
                    } else {
                        msg.setText(edMsg.getText());          // erro de sintaxe: continua na tela cheia
                    }
                }
            });
            dlg.setOnCancelListener(new android.content.DialogInterface.OnCancelListener() {
                public void onCancel(android.content.DialogInterface x) {
                    editor.setText(et.getText().toString());   // voltar do celular = VOLTAR
                }
            });
            dlg.setOnDismissListener(new android.content.DialogInterface.OnDismissListener() {
                public void onDismiss(android.content.DialogInterface x) {
                    a.setRequestedOrientation(prevOrientation);  // volta para paisagem
                    root.postDelayed(new Runnable() {
                        public void run() {
                            applyPanelLayout();                  // a tela mudou de tamanho duas vezes
                        }
                    }, 400);
                }
            });
            a.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);
            dlg.show();
        }

        // =====================================================================================
        // COPIAR (segurar o APPLY): coisas do frame atual em outros frames, como o "Copiar" do app
        // (FrameOps.applyTo): cada coisa marcada substitui a do frame de destino pela deste frame; se este
        // frame nao tem aquilo, o destino tambem fica sem. Trabalha direto no texto do 000.dac.txt.
        // =====================================================================================

        static final int C_IMG = 1, C_TIME = 2, C_MID = 4, C_HIT = 8, C_HURT = 16, C_RAZ = 32, C_SE = 64;
        static final String[] COPY_NAMES = {"Sprite", "Time", "X/Y ($MID)", "Hitbox", "Hurtbox", "RAZ (rot/alpha/zoom)", "SE (som)"};
        static final int[] COPY_BITS = {C_IMG, C_TIME, C_MID, C_HIT, C_HURT, C_RAZ, C_SE};
        /** Como no app: sprite e time desmarcados de proposito. Fica lembrado entre um uso e outro. */
        static int copyMask = C_MID | C_HIT | C_HURT | C_RAZ | C_SE;
        static final int T_ALL = 0, T_NEXT = 1, T_PREV = 2, T_SPR_ANO = 3, T_SPR_ALL = 4;
        static int copyTarget = T_NEXT;
        static int copyN = 1;
        static boolean copying;

        /** Segurar o APPLY: escolher o que copiar e para onde. */
        static void openCopyDialog() {
            final android.app.Activity a = act();
            if (a == null || !blockOk || tab != TAB_BASIC || copying) {
                return;
            }
            float d = dp();
            android.widget.ScrollView sv = new android.widget.ScrollView(a);
            android.widget.LinearLayout box = new android.widget.LinearLayout(a);
            box.setOrientation(android.widget.LinearLayout.VERTICAL);
            box.setPadding((int) (16 * d), (int) (8 * d), (int) (16 * d), 0);
            sv.addView(box);

            android.widget.TextView h1 = new android.widget.TextView(a);
            h1.setText("O que copiar deste frame (ANO " + edAno + " · FRAME " + edPat + ")");
            h1.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            box.addView(h1);
            final android.widget.CheckBox[] cb = new android.widget.CheckBox[COPY_NAMES.length];
            for (int i = 0; i < COPY_NAMES.length; ++i) {
                cb[i] = new android.widget.CheckBox(a);
                cb[i].setText(COPY_NAMES[i]);
                cb[i].setChecked((copyMask & COPY_BITS[i]) != 0);
                box.addView(cb[i]);
            }

            android.widget.TextView h2 = new android.widget.TextView(a);
            h2.setText("Para onde");
            h2.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            h2.setPadding(0, (int) (10 * d), 0, 0);
            box.addView(h2);
            final android.widget.RadioGroup rg = new android.widget.RadioGroup(a);
            String[] tn = {"Todos os frames deste ANO", "Proximos N frames", "N frames anteriores",
                    "Frames com esta sprite (neste ANO)", "Frames com esta sprite (todos os ANOs)"};
            for (int i = 0; i < tn.length; ++i) {
                android.widget.RadioButton rb = new android.widget.RadioButton(a);
                rb.setText(tn[i]);
                rb.setId(1000 + i);
                rg.addView(rb);
            }
            rg.check(1000 + copyTarget);
            box.addView(rg);
            android.widget.LinearLayout nr = new android.widget.LinearLayout(a);
            nr.setOrientation(android.widget.LinearLayout.HORIZONTAL);
            nr.setGravity(android.view.Gravity.CENTER_VERTICAL);
            android.widget.TextView nl = new android.widget.TextView(a);
            nl.setText("N = ");
            nr.addView(nl);
            final android.widget.EditText ne = new android.widget.EditText(a);
            ne.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);
            ne.setText(String.valueOf(copyN));
            ne.setSelectAllOnFocus(true);
            ne.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI | android.view.inputmethod.EditorInfo.IME_FLAG_NO_FULLSCREEN);
            nr.addView(ne, new android.widget.LinearLayout.LayoutParams((int) (80 * d), android.view.ViewGroup.LayoutParams.WRAP_CONTENT));
            box.addView(nr);
            android.widget.TextView note = new android.widget.TextView(a);
            note.setText("Cada coisa marcada substitui a do frame de destino pela deste frame; se este frame nao tem aquilo, "
                    + "o destino tambem fica sem. O dano/opcoes ($OPT) dos frames de destino nao mudam.");
            note.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, 11);
            note.setPadding(0, (int) (6 * d), 0, (int) (8 * d));
            box.addView(note);

            android.app.AlertDialog.Builder b = new android.app.AlertDialog.Builder(a);
            b.setTitle("Copiar");
            b.setView(sv);
            b.setPositiveButton("COPIAR", new android.content.DialogInterface.OnClickListener() {
                public void onClick(android.content.DialogInterface x, int w) {
                    int mask = 0;
                    for (int i = 0; i < cb.length; ++i) {
                        if (cb[i].isChecked()) {
                            mask |= COPY_BITS[i];
                        }
                    }
                    int n = 1;
                    try {
                        n = Math.max(1, Integer.parseInt(ne.getText().toString().trim()));
                    } catch (NumberFormatException e) {
                        n = 1;
                    }
                    copyMask = mask;
                    copyTarget = Math.max(0, rg.getCheckedRadioButtonId() - 1000);
                    copyN = n;
                    if (mask == 0) {
                        toast("nada marcado para copiar");
                        return;
                    }
                    startCopy();
                }
            });
            b.setNegativeButton("CANCELAR", null);
            android.app.AlertDialog dlg = b.create();
            dlg.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_HIDDEN);
            dlg.show();
        }

        /** Grava o frame atual (se mudou) e copia numa thread; no fim: "Copiado, reinicie para aplicar". */
        static void startCopy() {
            if (isDirty() && !confirm()) {
                return;                                  // o frame de origem tem erro de sintaxe
            }
            final String dir = curDir();
            if (dir == null) {
                return;
            }
            final int rslot = globalMode ? edSlot : -1;
            final String path = fileOf(TAB_MPT, dir);
            final String src = basicText;
            final int ano = edAno, pat = edPat, mask = copyMask, target = copyTarget, n = copyN;
            copying = true;
            setMsg("copiando...", 0xFF9AA4B4);
            new Thread(new Runnable() {
                public void run() {
                    String res;
                    boolean ok = false;
                    int count = 0;
                    try {
                        java.io.File f = new java.io.File(path);
                        String text = readText(f);
                        String before = text;
                        int[] cnt = new int[1];
                        text = copyFrames(text, src, ano, pat, mask, target, n, cnt);
                        count = cnt[0];
                        if (count > 0) {
                            java.io.File bak = new java.io.File(path + ".antes_editor");
                            if (!bak.exists()) {
                                writeText(bak, before);
                            }
                            writeText(f, text);
                            undo.add(new Object[]{path, Integer.valueOf(-1), Integer.valueOf(0), Integer.valueOf(ano), Integer.valueOf(pat), before});
                            markReload(rslot);
                        }
                        ok = true;
                        res = count == 0 ? "nenhum frame de destino" : "Copiado em " + count + " frame(s), reinicie para aplicar";
                    } catch (Throwable e) {
                        res = "nao copiado: " + e.getMessage();
                    }
                    final String fres = res;
                    final boolean fok = ok;
                    final int fcount = count;
                    ui.post(new Runnable() {
                        public void run() {
                            copying = false;
                            setMsg(fres, fok ? (fcount > 0 ? 0xFF7CE08A : 0xFFFFC060) : 0xFFFF8080);
                            toast(fres);
                            if (fok && fcount > 0 && !isDirty()) {
                                savedJustNow = true;     // APPLY vira REINICIAR
                                refreshSaveButtons();
                            }
                        }
                    });
                }
            }, "EditModeCopy").start();
        }

        /** Numeros dos $MPT_n do $ANO_ano (fora de comentario), em ordem. */
        static java.util.ArrayList<Integer> mptNums(String text, int ano) {
            java.util.ArrayList<Integer> out = new java.util.ArrayList<Integer>();
            int[] ab = findBlock(text, "ANO_" + ano, 0, text.length());
            if (ab == null) {
                return out;
            }
            java.util.regex.Matcher m = java.util.regex.Pattern.compile("\\$MPT_(\\d+)\\s*:\\s*\\{").matcher(text);
            m.region(ab[1] + 1, ab[2]);
            while (m.find()) {
                if (!inComment(text, m.start())) {
                    out.add(Integer.valueOf(Integer.parseInt(m.group(1))));
                }
            }
            return out;
        }

        /** Numeros dos $ANO_n do arquivo (fora de comentario), em ordem. */
        static java.util.ArrayList<Integer> anoList(String text) {
            java.util.ArrayList<Integer> out = new java.util.ArrayList<Integer>();
            java.util.regex.Matcher m = java.util.regex.Pattern.compile("\\$ANO_(\\d+)\\s*:\\s*\\{").matcher(text);
            while (m.find()) {
                if (!inComment(text, m.start())) {
                    out.add(Integer.valueOf(Integer.parseInt(m.group(1))));
                }
            }
            return out;
        }

        static int mptIndex(TNode n) {
            String k = n.key.toUpperCase(java.util.Locale.US);
            if (!k.startsWith("MPT_")) {
                return -1;
            }
            try {
                return Integer.parseInt(k.substring(4));
            } catch (NumberFormatException e) {
                return -1;
            }
        }

        static Integer scalar(String t, TNode n, String key) {
            TNode c = n == null ? null : n.kid(key);
            return c == null || c.kids != null || c.ts.length > 0 ? null : Integer.valueOf(toInt(t.substring(c.vs, c.ve)));
        }

        /** Aplica a copia em todos os frames de destino. cnt[0] = quantos frames mudaram. */
        static String copyFrames(String text, String src, int srcAno, int srcPat, int mask, int target, int n, int[] cnt) throws SynErr {
            TNode st = parseTree(src);
            Integer srcImg = scalar(src, st, "IMG");
            java.util.ArrayList<Integer> anos = new java.util.ArrayList<Integer>();
            if (target == T_SPR_ALL) {
                anos.addAll(anoList(text));
            } else {
                anos.add(Integer.valueOf(srcAno));
            }
            for (int ai = 0; ai < anos.size(); ++ai) {
                int ano = anos.get(ai).intValue();
                int[] a = findBlock(text, "ANO_" + ano, 0, text.length());
                if (a == null) {
                    continue;
                }
                String at = text.substring(a[0], a[2] + 1);
                TNode an;
                try {
                    an = parseTree(at);
                } catch (SynErr e) {
                    continue;                            // ANO com texto que nao da para ler: fica como esta
                }
                TNode mpts = an.kid("MPTS");
                if (mpts == null || mpts.kids == null) {
                    continue;
                }
                int len = 0;
                for (int k = 0; k < mpts.kids.size(); ++k) {
                    len = Math.max(len, mptIndex(mpts.kids.get(k)) + 1);
                }
                int from = 0, to = len - 1;
                if (target == T_NEXT) {
                    from = srcPat + 1;
                    to = Math.min(len - 1, srcPat + n);
                } else if (target == T_PREV) {
                    from = Math.max(0, srcPat - n);
                    to = srcPat - 1;
                }
                // de tras para frente: as posicoes das MPTs anteriores continuam valendo
                java.util.ArrayList<int[]> spans = new java.util.ArrayList<int[]>();
                java.util.ArrayList<String> repl = new java.util.ArrayList<String>();
                for (int k = 0; k < mpts.kids.size(); ++k) {
                    TNode mk = mpts.kids.get(k);
                    int idx = mptIndex(mk);
                    if (idx < 0 || mk.kids == null || (ano == srcAno && idx == srcPat) || idx < from || idx > to) {
                        continue;
                    }
                    String ind = lineIndent(at, mk.ks);
                    String blk = deindent(at.substring(mk.ks, mk.ve), ind);
                    if (target == T_SPR_ANO || target == T_SPR_ALL) {
                        Integer img;
                        try {
                            img = scalar(blk, parseTree(blk), "IMG");
                        } catch (SynErr e) {
                            continue;
                        }
                        if (srcImg == null || img == null || img.intValue() != srcImg.intValue()) {
                            continue;
                        }
                    }
                    String nb;
                    try {
                        nb = copyInto(src, blk, mask);
                    } catch (SynErr e) {
                        continue;
                    }
                    if (!nb.equals(blk)) {
                        spans.add(new int[]{mk.ks, mk.ve});
                        repl.add(reindent(nb, ind));
                    }
                }
                for (int k = spans.size() - 1; k >= 0; --k) {
                    int[] sp = spans.get(k);
                    at = at.substring(0, sp[0]) + repl.get(k) + at.substring(sp[1]);
                    cnt[0]++;
                }
                text = text.substring(0, a[0]) + at + text.substring(a[2] + 1);
            }
            return text;
        }

        /** Tira a entrada do texto (com a virgula; a linha some se ficar vazia). */
        static String removeEntry(String t, TNode n) {
            int s = n.ks;
            int e = n.ve;
            while (e < t.length() && (t.charAt(e) == ' ' || t.charAt(e) == '\t')) {
                e++;
            }
            if (e < t.length() && t.charAt(e) == ',') {
                e++;
            }
            while (e < t.length() && (t.charAt(e) == ' ' || t.charAt(e) == '\t')) {
                e++;
            }
            int ls = t.lastIndexOf('\n', s - 1) + 1;
            boolean aloneStart = t.substring(ls, s).trim().isEmpty();
            boolean aloneEnd = e >= t.length() || t.charAt(e) == '\n';
            if (aloneStart && aloneEnd && ls > 0) {
                return t.substring(0, ls - 1) + t.substring(e);      // linha inteira
            }
            return t.substring(0, s) + t.substring(e);
        }

        /** Insere uma linha nova (com a indentacao dos campos) antes de {@code before} ou antes do '}' final. */
        static String insertLine(String t, TNode root, TNode before, String entry) {
            int pos;
            String ind;
            if (before != null) {
                pos = t.lastIndexOf('\n', before.ks - 1) + 1;
                ind = lineIndent(t, before.ks);
            } else {
                int close = root.ve - 1;                             // o '}' do MPT
                pos = t.lastIndexOf('\n', close - 1) + 1;
                if (!t.substring(pos, close).trim().isEmpty()) {
                    return t.substring(0, close) + " " + entry + ", " + t.substring(close);
                }
                ind = lineIndent(t, close) + "   ";
            }
            return t.substring(0, pos) + ind + entry + ",\n" + t.substring(pos);
        }

        /** Escalar/lista na linha do $IMG: troca, cria (antes ou depois do $IMG) ou tira. */
        static String copyInline(String src, TNode s, String dst, String key, boolean beforeImg) throws SynErr {
            TNode d = parseTree(dst);
            TNode sv = s.kid(key);
            TNode dv = d.kid(key);
            if (sv == null) {
                return dv == null ? dst : removeEntry(dst, dv);
            }
            String val = src.substring(sv.vs, sv.ve);
            if (dv != null) {
                return dst.substring(0, dv.vs) + val + dst.substring(dv.ve);
            }
            TNode img = d.kid("IMG");
            if (img == null) {
                return insertLine(dst, d, null, "$" + key + ": " + val);
            }
            String sep = key.equals("MID") ? "" : " ";
            TNode after = key.equals("SE") && d.kid("MID") != null ? d.kid("MID") : img;   // ordem do app: IMG, MID, SE
            return beforeImg ? dst.substring(0, img.ks) + "$" + key + ":" + sep + val + ", " + dst.substring(img.ks)
                    : dst.substring(0, after.ve) + ", $" + key + ":" + sep + val + dst.substring(after.ve);
        }

        static int hitFlag(String t, TNode h) {
            Integer f = scalar(t, h, "FLAG");
            return f == null ? -1 : f.intValue();
        }

        /** Copia as coisas marcadas do bloco {@code src} sobre o bloco {@code dst} (os dois "$MPT_n:{...}"). */
        static String copyInto(String src, String dst, int mask) throws SynErr {
            TNode s = parseTree(src);
            if ((mask & C_IMG) != 0 && s.kid("IMG") != null) {
                dst = copyInline(src, s, dst, "IMG", false);
            }
            if ((mask & C_TIME) != 0) {
                dst = copyInline(src, s, dst, "TIME", true);
            }
            if ((mask & C_MID) != 0) {
                dst = copyInline(src, s, dst, "MID", false);
            }
            if ((mask & C_SE) != 0) {
                dst = copyInline(src, s, dst, "SE", false);
            }
            if ((mask & (C_HIT | C_HURT)) != 0) {
                // mantem as caixas do destino que nao foram marcadas e poe as marcadas da origem (como o app)
                TNode d = parseTree(dst);
                java.util.ArrayList<String> vals = new java.util.ArrayList<String>();
                TNode dh = d.kid("HITS");
                if (dh != null && dh.kids != null) {
                    for (int i = 0; i < dh.kids.size(); ++i) {
                        int f = hitFlag(dst, dh.kids.get(i));
                        boolean sel = (f == 2 && (mask & C_HIT) != 0) || (f == 1 && (mask & C_HURT) != 0);
                        if (!sel) {
                            vals.add(dst.substring(dh.kids.get(i).vs, dh.kids.get(i).ve));
                        }
                    }
                }
                TNode sh = s.kid("HITS");
                if (sh != null && sh.kids != null) {
                    for (int i = 0; i < sh.kids.size(); ++i) {
                        int f = hitFlag(src, sh.kids.get(i));
                        boolean sel = (f == 2 && (mask & C_HIT) != 0) || (f == 1 && (mask & C_HURT) != 0);
                        if (sel) {
                            vals.add(src.substring(sh.kids.get(i).vs, sh.kids.get(i).ve));
                        }
                    }
                }
                if (dh != null) {
                    if (vals.isEmpty()) {
                        dst = removeEntry(dst, dh);
                    } else {
                        String ind = lineIndent(dst, dh.ks);
                        StringBuilder sb = new StringBuilder("{\n");
                        for (int i = 0; i < vals.size(); ++i) {
                            sb.append(ind).append("   $HT_").append(i).append(':').append(vals.get(i)).append(",\n");
                        }
                        sb.append(ind).append('}');
                        dst = dst.substring(0, dh.vs) + sb + dst.substring(dh.ve);
                    }
                } else if (!vals.isEmpty()) {
                    TNode before = d.kid("OPT") != null ? d.kid("OPT") : d.kid("RAZ");
                    String ind = before != null ? lineIndent(dst, before.ks) : "   ";
                    StringBuilder sb = new StringBuilder("$HITS:{\n");
                    for (int i = 0; i < vals.size(); ++i) {
                        sb.append(ind).append("   $HT_").append(i).append(':').append(vals.get(i)).append(",\n");
                    }
                    sb.append(ind).append('}');
                    dst = insertLine(dst, d, before, sb.toString());
                }
            }
            if ((mask & C_RAZ) != 0) {
                TNode d = parseTree(dst);
                TNode sr = s.kid("RAZ");
                TNode dr = d.kid("RAZ");
                if (sr == null) {
                    if (dr != null) {
                        dst = removeEntry(dst, dr);
                    }
                } else if (dr != null) {
                    dst = dst.substring(0, dr.vs) + src.substring(sr.vs, sr.ve) + dst.substring(dr.ve);
                } else {
                    dst = insertLine(dst, d, null, "$RAZ:" + src.substring(sr.vs, sr.ve));
                }
            }
            return dst;
        }

        /** Troca entre as abas MPT e BASICO sem perder o que foi digitado/alterado. */
        static void switchKeepingText(int nt) {
            String cur = currentText();
            String loaded = loadedText;
            boolean saved = savedJustNow;
            tab = nt;
            showBlock(cur, edMsg.getText().toString(), true);
            loadedText = loaded;                         // continua "nao salvo" se estava
            savedJustNow = saved && !isDirty();
            refreshSaveButtons();
            refreshLabels();
        }

        /** Um +tick/+frame terminou: o editor segue o golpe/ANO/MPT novo (se nao tiver alteracao pendente). */
        static void onGameStepped() {
            if (!panelOpen || globalMode) {
                return;
            }
            if (followAfterStep || !isDirty()) {
                followAfterStep = false;
                loadTab(true);
            } else {
                setMsg("alteracao nao salva: salve ou redefina para seguir o jogo", 0xFFFFC060);
            }
        }

        // ---- carregar / salvar ---------------------------------------------------------------

        /** Carrega o bloco da aba atual. follow = pega golpe/ANO/MPT do que esta acontecendo no jogo. */
        static void loadTab(boolean follow) {
            int pi = refPlayer == 1 ? 1 : 0;
            if (follow && !globalMode) {
                edGolpe = Math.max(0, lastGolpe);
                edAno = pubAno[pi];
                edPat = pubPat[pi];
            }
            edLoaded = true;
            String dir = curDir();
            String key = blockKey(tab, edGolpe, edAno, edPat);
            int bt = blockTab(tab);
            String where = bt == TAB_MPT ? "ANO " + edAno + " · MPT " + edPat : (bt == TAB_ANO ? "ANO " + edAno : "GOLPE " + edGolpe);
            edLabel.setText(where);
            blockOk = false;
            loadedText = "";
            if (dir == null) {
                showBlock("", globalMode ? "pack sem pasta" : "personagem sem pasta", false);
                return;
            }
            String path = fileOf(tab, dir);
            String fname = new java.io.File(dir).getName() + "/" + new java.io.File(path).getName();
            try {
                String text = readText(new java.io.File(path));
                int[] b = locateBlock(text, tab, edGolpe, edAno, edPat);
                if (b == null) {
                    showBlock("", "$" + key + " nao existe em " + fname, false);
                    return;
                }
                showBlock(deindent(text.substring(b[0], b[2] + 1), lineIndent(text, b[0])), fname, true);
            } catch (java.io.IOException e) {
                showBlock("", "nao consegui ler " + path + ": " + e.getMessage(), false);
            }
        }

        static void showBlock(String text, String msg, boolean ok) {
            savedJustNow = false;
            blockOk = ok;
            loadedText = text;
            basicText = text;
            boolean basic = tab == TAB_BASIC;
            applyPanelLayout();
            ignoreWatcher = true;
            editor.setText(text);
            ignoreWatcher = false;
            editor.setEnabled(ok);
            editor.scrollTo(0, 0);
            btnConfirm.setEnabled(ok);
            setMsg(msg, ok ? 0xFF9AA4B4 : 0xFFFF8080);
            refreshSaveButtons();
            if (basic) {
                buildForm();
                if (ok) {
                    publishLive();
                }
            }
        }

        static void setMsg(String s, int color) {
            edMsg.setTextColor(color);
            edMsg.setText(s);
        }

        /** Grava o bloco da aba. true = salvo. */
        static boolean confirm() {
            String dir = curDir();
            if (dir == null || !blockOk) {
                return false;
            }
            String key = blockKey(tab, edGolpe, edAno, edPat);
            String text = currentText().trim();
            if (text.endsWith(",")) {
                text = text.substring(0, text.length() - 1).trim();
            }
            String err = checkSyntax(text, key);
            if (err != null) {
                setMsg("NAO SALVO: " + err, 0xFFFF8080);
                return false;
            }
            String path = fileOf(tab, dir);
            try {
                String prev = replaceBlock(path, tab, edGolpe, edAno, edPat, text);
                undo.add(new Object[]{path, Integer.valueOf(blockTab(tab)), Integer.valueOf(edGolpe), Integer.valueOf(edAno), Integer.valueOf(edPat), prev});
                if (globalMode) {
                    markReload(edSlot);
                }
                hideKeyboard();
                loadedText = currentText();
                setMsg("salvo em " + new java.io.File(dir).getName() + "/" + new java.io.File(path).getName()
                        + " — toque em ⟳ para ver no jogo", 0xFF7CE08A);
                return true;
            } catch (java.io.IOException e) {
                setMsg("NAO SALVO: " + e.getMessage(), 0xFFFF8080);
                return false;
            }
        }

        static void undoLast() {
            if (undo.isEmpty()) {
                toast("nada para desfazer");
                return;
            }
            Object[] u = undo.remove(undo.size() - 1);
            String path = (String) u[0];
            int t = ((Integer) u[1]).intValue();
            int g = ((Integer) u[2]).intValue();
            int a = ((Integer) u[3]).intValue();
            int p = ((Integer) u[4]).intValue();
            if (t == -1) {
                // copia para outros frames: volta o arquivo inteiro como estava
                try {
                    writeText(new java.io.File(path), (String) u[5]);
                    if (globalMode) {
                        markReload(edSlot);
                    }
                    loadTab(false);
                    setMsg("copia desfeita — reinicie para aplicar", 0xFF7CE08A);
                } catch (java.io.IOException e) {
                    setMsg("nao desfeito: " + e.getMessage(), 0xFFFF8080);
                }
                refreshLabels();
                return;
            }
            try {
                replaceBlock(path, t, g, a, p, (String) u[5]);
                if (globalMode) {
                    markReload(edSlot);          // fica no ANO/frame aberto; so recarrega
                } else {
                    if (tab != TAB_BASIC || t != TAB_MPT) {
                        tab = t;
                    }
                    edGolpe = g;
                    edAno = a;
                    edPat = p;
                }
                loadTab(false);
                setMsg("desfeito em " + new java.io.File(path).getName() + " — toque em ⟳ para ver no jogo", 0xFF7CE08A);
            } catch (java.io.IOException e) {
                setMsg("nao desfeito: " + e.getMessage(), 0xFFFF8080);
            }
            refreshLabels();
        }

        // =====================================================================================
        // Aba BASICO: o MPT atual em controles - N +
        // =====================================================================================

        static final int F_SCALAR = 0, F_LIST = 1, F_RAZ = 2, F_HIT = 3;

        /** Um campo do MPT: $IMG/$TIME/$SE (escalar), $MID[i] (lista), $RAZ.$X, ou $HITS.$HT_n.$COORDS[i]. */
        static final class Field {
            final int kind;
            final String key;
            final int idx;
            final int min, max;
            android.widget.TextView value;

            Field(int kind, String key, int idx, int min, int max) {
                this.kind = kind;
                this.key = key;
                this.idx = idx;
                this.min = min;
                this.max = max;
            }
        }

        static final java.util.ArrayList<Field> fields = new java.util.ArrayList<Field>();
        static android.widget.TextView timeSec;
        static android.widget.ImageView thumb;
        static int thumbImg = Integer.MIN_VALUE;

        static TNode basicTree() {
            try {
                return parseTree(basicText);
            } catch (SynErr e) {
                return null;
            }
        }

        static int toInt(String s) {
            s = s.trim();
            try {
                if (s.startsWith("&")) {
                    return (int) Long.parseLong(s.substring(1), 16);
                }
                return (int) Math.round(Double.parseDouble(s));
            } catch (NumberFormatException e) {
                return 0;
            }
        }

        /** {inicio, fim} do numero do campo no texto, ou null. */
        static int[] span(TNode t, Field f) {
            TNode n;
            switch (f.kind) {
                case F_SCALAR:
                    n = t.kid(f.key);
                    return n == null || n.kids != null || n.ts.length > 0 ? null : new int[]{n.vs, n.ve};
                case F_LIST:
                    n = t.kid(f.key);
                    return n == null || f.idx >= n.ts.length ? null : new int[]{n.ts[f.idx], n.te[f.idx]};
                case F_RAZ:
                    n = t.kid("RAZ");
                    n = n == null ? null : n.kid(f.key);
                    return n == null ? null : new int[]{n.vs, n.ve};
                default:
                    n = t.kid("HITS");
                    n = n == null ? null : n.kid(f.key);
                    n = n == null ? null : n.kid("COORDS");
                    return n == null || f.idx >= n.ts.length ? null : new int[]{n.ts[f.idx], n.te[f.idx]};
            }
        }

        static Integer getField(Field f) {
            TNode t = basicTree();
            int[] s = t == null ? null : span(t, f);
            return s == null ? null : Integer.valueOf(toInt(basicText.substring(s[0], s[1])));
        }

        static void setField(Field f, int v) {
            TNode t = basicTree();
            int[] s = t == null ? null : span(t, f);
            if (s == null) {
                return;
            }
            int max = f.max;
            if (f.kind == F_SCALAR && "IMG".equals(f.key)) {
                max = imgMax();                  // nao passa da ultima sprite
            }
            v = Math.max(f.min, Math.min(max, v));
            basicText = basicText.substring(0, s[0]) + v + basicText.substring(s[1]);
            refreshForm();
            publishLive();
            markChanged();
        }

        /**
         * Maior indice de sprite: o que o jogo carregou ou o que a lista de sprites conhece (inclui as
         * adicionadas agora, que aparecem no jogo so depois de reiniciar).
         */
        static int imgMax() {
            int n = globalMode ? edImgCount : pubImgCount;
            try {
                String dir = curDir();
                if (dir != null) {
                    n = Math.max(n, com.zue.attackeditor.GameEditBridge.spriteCount(new java.io.File(dir)));
                }
            } catch (Throwable e) {
                // sem o pacote do editor: fica so com o CNV carregado
            }
            return Math.max(0, n - 1);
        }

        /** Manda para o jogo os valores do MPT da aba BASICO (aparece na hora no objeto). */
        static void publishLive() {
            TNode t = basicTree();
            if (t == null || !blockOk) {
                return;
            }
            LiveFrame lf = new LiveFrame();
            lf.slot = curSlot();
            if (lf.slot < 0 || lf.slot >= 31) {
                return;
            }
            lf.act = CreatedAct[lf.slot];
            lf.ano = edAno;
            lf.pat = edPat;
            TNode n = t.kid("IMG");
            if (n != null && n.kids == null && n.ts.length == 0) {
                lf.hasImg = true;
                lf.img = toInt(basicText.substring(n.vs, n.ve));
            }
            n = t.kid("TIME");
            if (n != null && n.kids == null && n.ts.length == 0) {
                lf.hasTime = true;
                lf.time = toInt(basicText.substring(n.vs, n.ve));
            }
            n = t.kid("MID");
            if (n != null && n.ts.length >= 2) {
                lf.hasMid = true;
                lf.midX = toInt(basicText.substring(n.ts[0], n.te[0]));
                lf.midY = toInt(basicText.substring(n.ts[1], n.te[1]));
            }
            n = t.kid("RAZ");
            if (n != null && n.kids != null) {
                lf.hasRaz = true;
                String[] keys = {"ROT", "ALPHA", "XZOOM", "YZOOM"};
                for (int k = 0; k < 4; ++k) {
                    TNode c = n.kid(keys[k]);
                    if (c != null) {
                        lf.raz[k] = toInt(basicText.substring(c.vs, c.ve));
                    }
                }
            }
            n = globalMode && !edIsChar() ? null : t.kid("HITS");     // caixas so de personagem
            if (n != null && n.kids != null) {
                java.util.ArrayList<int[]> hs = new java.util.ArrayList<int[]>();
                for (int i = 0; i < n.kids.size(); ++i) {
                    TNode co = n.kids.get(i).kid("COORDS");
                    int[] v4 = new int[4];
                    for (int k = 0; co != null && k < 4 && k < co.ts.length; ++k) {
                        v4[k] = toInt(basicText.substring(co.ts[k], co.te[k]));
                    }
                    hs.add(v4);
                }
                lf.hits = hs.toArray(new int[hs.size()][]);
            }
            liveQueue.add(lf);
        }

        /** Insere um campo que o frame nao tem ($TIME antes do $IMG, $MID logo depois do $IMG). */
        static void addField(String what) {
            TNode t = basicTree();
            if (t == null) {
                return;
            }
            TNode img = t.kid("IMG");
            if ("RAZ".equals(what)) {
                String raz = "$RAZ:{$ROT: 0, $ALPHA: 0, $XZOOM: 100, $YZOOM: 100}";
                TNode last = t.kids.isEmpty() ? null : t.kids.get(t.kids.size() - 1);
                int at;
                String ins;
                if (last == null) {
                    at = t.vs + 1;
                    ins = "\n   " + raz + ",\n";
                } else {
                    String ind = lineIndent(basicText, last.ks);
                    if (ind.length() == 0) {
                        ind = "   ";
                    }
                    at = last.ve;
                    int q = at;
                    while (q < basicText.length() && (basicText.charAt(q) == ' ' || basicText.charAt(q) == '\t')) {
                        q++;
                    }
                    if (q < basicText.length() && basicText.charAt(q) == ',') {
                        at = q + 1;
                        ins = "\n" + ind + raz + ",";
                    } else {
                        ins = ",\n" + ind + raz;
                    }
                }
                basicText = basicText.substring(0, at) + ins + basicText.substring(at);
            } else if ("TIME".equals(what)) {
                int at = img != null ? img.ks : t.vs + 1;
                basicText = basicText.substring(0, at) + (img != null ? "$TIME: 1, " : "\n   $TIME: 1,") + basicText.substring(at);
            } else {
                int at = img != null ? img.ve : t.vs + 1;
                basicText = basicText.substring(0, at) + (img != null ? ", $MID:[0, 0]" : "\n   $MID:[0, 0],") + basicText.substring(at);
            }
            buildForm();
            publishLive();
            markChanged();
        }

        static void refreshForm() {
            for (int i = 0; i < fields.size(); ++i) {
                Field f = fields.get(i);
                Integer v = getField(f);
                if (f.value != null) {
                    f.value.setText(v == null ? "?" : String.valueOf(v.intValue()));
                }
                if ("TIME".equals(f.key) && f.kind == F_SCALAR && timeSec != null && v != null) {
                    timeSec.setText(String.format(java.util.Locale.US, "%.2fs", v.intValue() / 60.0));
                }
                if ("IMG".equals(f.key) && f.kind == F_SCALAR && v != null) {
                    loadThumb(v.intValue());
                }
            }
        }

        static int thumbWanted = Integer.MIN_VALUE;

        static final Runnable THUMB_LOAD = new Runnable() {
            public void run() {
                loadThumbNow(thumbWanted);
            }
        };

        /** Miniatura da sprite: so carrega quando o numero para de mudar por um instante. */
        static void loadThumb(int img) {
            if (thumb == null || img == thumbImg) {
                return;
            }
            thumbWanted = img;
            ui.removeCallbacks(THUMB_LOAD);
            ui.postDelayed(THUMB_LOAD, 120);
        }

        static void loadThumbNow(final int img) {
            if (thumb == null || img == thumbImg) {
                return;
            }
            thumbImg = img;
            thumb.setImageDrawable(null);
            String dir = curDir();
            if (dir == null || img < 0) {
                return;
            }
            try {
                com.zue.attackeditor.GameEditBridge.spriteThumb(new java.io.File(dir), curIsChar(), img, new com.zue.attackeditor.GameEditBridge.Thumb() {
                    public void onThumb(int image, android.graphics.Bitmap b) {
                        if (thumb != null && image == thumbImg) {
                            thumb.setImageBitmap(b);
                        }
                    }
                });
            } catch (Throwable e) {
                android.util.Log.e(TAG, "previa da sprite", e);
            }
        }

        /** Um passo de - / + (tag = {Field, +1/-1}). */
        static void stepField(android.view.View v) {
            Object tag = v.getTag();
            if (tag instanceof Object[]) {
                Object[] o = (Object[]) tag;
                Field f = (Field) o[0];
                Integer cur = getField(f);
                if (cur != null) {
                    setField(f, cur.intValue() + ((Integer) o[1]).intValue());
                }
            }
        }

        static final int REPEAT_FIRST_MS = 350;   // segurando: espera isso e depois...
        static final int REPEAT_MS = 55;          // ...anda 1 a cada 55 ms (o jogo mostra cada passo ao vivo)
        static android.view.View repeating;

        static final Runnable REPEAT = new Runnable() {
            public void run() {
                android.view.View v = repeating;
                if (v == null || !v.isPressed()) {
                    repeating = null;
                    return;
                }
                stepField(v);
                ui.postDelayed(this, REPEAT_MS);
            }
        };

        /** - / +: toque anda 1; segurando continua andando de 1 em 1 ate soltar. */
        static final android.view.View.OnTouchListener STEP_TOUCH = new android.view.View.OnTouchListener() {
            public boolean onTouch(android.view.View v, android.view.MotionEvent ev) {
                switch (ev.getActionMasked()) {
                    case android.view.MotionEvent.ACTION_DOWN:
                        v.setPressed(true);
                        stepField(v);
                        repeating = v;
                        ui.removeCallbacks(REPEAT);
                        ui.postDelayed(REPEAT, REPEAT_FIRST_MS);
                        return true;
                    case android.view.MotionEvent.ACTION_MOVE:
                        return true;
                    default:                         // UP / CANCEL
                        v.setPressed(false);
                        repeating = null;
                        ui.removeCallbacks(REPEAT);
                        return true;
                }
            }
        };

        /** Toque no numero: digita o valor. */
        static void askValue(final Field f, String title) {
            android.app.Activity a = act();
            Integer cur = getField(f);
            if (a == null || cur == null) {
                return;
            }
            final android.widget.EditText e = new android.widget.EditText(a);
            e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_SIGNED);
            e.setText(String.valueOf(cur.intValue()));
            e.setSelectAllOnFocus(true);
            e.setImeOptions(android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI | android.view.inputmethod.EditorInfo.IME_FLAG_NO_FULLSCREEN);
            android.app.AlertDialog.Builder b = new android.app.AlertDialog.Builder(a);
            b.setTitle(title);
            b.setView(e);
            b.setPositiveButton("OK", new android.content.DialogInterface.OnClickListener() {
                public void onClick(android.content.DialogInterface d, int w) {
                    try {
                        setField(f, Integer.parseInt(e.getText().toString().trim()));
                    } catch (NumberFormatException ex) {
                        toast("valor invalido");
                    }
                }
            });
            b.setNegativeButton("CANCELAR", null);
            android.app.AlertDialog dlg = b.create();
            dlg.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_VISIBLE);
            dlg.show();
        }

        /** Botao pequeno da tela compacta. */
        static android.widget.Button miniButton(android.view.ViewGroup parent, String text, float weight) {
            android.app.Activity a = act();
            float d = dp();
            android.widget.Button b = new android.widget.Button(a);
            b.setAllCaps(false);
            b.setText(text);
            b.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, 11);
            b.setTextColor(0xFFFFFFFF);
            b.setBackgroundColor(0xFF2A303C);
            b.setMinHeight(0);
            b.setMinimumHeight(0);
            b.setMinWidth((int) (26 * d));
            b.setMinimumWidth((int) (26 * d));
            b.setSingleLine(true);
            b.setPadding((int) (3 * d), (int) (4 * d), (int) (3 * d), (int) (4 * d));
            android.widget.LinearLayout.LayoutParams lp = weight > 0
                    ? new android.widget.LinearLayout.LayoutParams(0, android.view.ViewGroup.LayoutParams.WRAP_CONTENT, weight)
                    : new android.widget.LinearLayout.LayoutParams(android.view.ViewGroup.LayoutParams.WRAP_CONTENT, android.view.ViewGroup.LayoutParams.WRAP_CONTENT);
            int m = Math.max(1, (int) d);
            lp.setMargins(m, m, m, m);
            parent.addView(b, lp);
            return b;
        }

        /** [rotulo] [-] N [+] compacto (meia linha). */
        static android.widget.LinearLayout stepper(android.view.ViewGroup parent, final String label, final Field f, float weight) {
            android.app.Activity a = act();
            float d = dp();
            android.widget.LinearLayout r = new android.widget.LinearLayout(a);
            r.setOrientation(android.widget.LinearLayout.HORIZONTAL);
            r.setGravity(android.view.Gravity.CENTER_VERTICAL);
            android.widget.TextView l = label(a, label, 10, 0xFFB8C0CC);
            l.setPadding((int) (3 * d), 0, (int) (2 * d), 0);
            l.setMinWidth((int) (26 * d));
            r.addView(l);
            android.widget.Button minus = miniButton(r, "−", 0);
            minus.setOnTouchListener(STEP_TOUCH);
            minus.setTag(new Object[]{f, Integer.valueOf(-1)});
            android.widget.TextView val = label(a, "", 12, 0xFFFFFFFF);
            val.setTypeface(android.graphics.Typeface.MONOSPACE, android.graphics.Typeface.BOLD);
            val.setGravity(android.view.Gravity.CENTER);
            val.setBackgroundColor(0xFF161A21);
            val.setSingleLine(true);
            val.setPadding(0, (int) (4 * d), 0, (int) (4 * d));
            val.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    askValue(f, label);
                }
            });
            r.addView(val, new android.widget.LinearLayout.LayoutParams(0, android.view.ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
            android.widget.Button plus = miniButton(r, "+", 0);
            plus.setOnTouchListener(STEP_TOUCH);
            plus.setTag(new Object[]{f, Integer.valueOf(1)});
            f.value = val;
            fields.add(f);
            android.widget.LinearLayout.LayoutParams lp = weight > 0
                    ? new android.widget.LinearLayout.LayoutParams(0, android.view.ViewGroup.LayoutParams.WRAP_CONTENT, weight)
                    : new android.widget.LinearLayout.LayoutParams(android.view.ViewGroup.LayoutParams.MATCH_PARENT, android.view.ViewGroup.LayoutParams.WRAP_CONTENT);
            parent.addView(r, lp);
            return r;
        }

        /** Linha com titulo pequeno a esquerda (ex.: "HIT1") e o resto do conteudo. */
        static android.widget.LinearLayout titledRow(String title, int color) {
            android.app.Activity a = act();
            android.widget.LinearLayout r = row(a, form);
            android.widget.TextView t = label(a, title, 9, color);
            t.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            t.setMinWidth((int) (34 * dp()));
            t.setPadding((int) (2 * dp()), 0, 0, 0);
            r.addView(t);
            return r;
        }

        /** Na tela compacta, sair do frame grava sozinho o que foi alterado nele. */
        static void autoSaveThen(Runnable then) {
            if (isDirty() && !confirm()) {
                return;                          // erro de sintaxe: fica no frame mostrando a mensagem
            }
            then.run();
        }

        static void buildForm() {
            android.app.Activity a = act();
            if (a == null) {
                return;
            }
            if (globalMode) {
                buildGlobalForm();
                return;
            }
            float d = dp();
            form.removeAllViews();
            fields.clear();
            timeSec = null;
            thumb = null;
            thumbImg = Integer.MIN_VALUE;

            // cabecalho: [Menu] ANO n FRAME n [>>] [↺ redefinir] [↶ desfazer] [▢ caixas] [APPLY]
            android.widget.LinearLayout r = row(a, form);
            android.widget.Button menu = miniButton(r, "Menu", 0);
            android.widget.TextView lb = label(a, "ANO " + edAno + "  FRAME " + edPat, 11, 0xFFFFFFFF);
            lb.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            lb.setGravity(android.view.Gravity.CENTER);
            lb.setSingleLine(true);
            r.addView(lb, new android.widget.LinearLayout.LayoutParams(0, android.view.ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
            android.widget.Button step = miniButton(r, "\u00BB", 0);
            step.setBackgroundColor(0xFF2B3F66);
            android.widget.Button redef = miniButton(r, "\u21BA", 0);
            android.widget.Button und = miniButton(r, "\u21B6", 0);
            final android.widget.Button boxes = miniButton(r, "\u25A2", 0);
            boxes.setBackgroundColor(showBoxes ? 0xFF3A7BFF : 0xFF2A303C);
            android.widget.Button save = miniButton(r, "APPLY", 0);
            compactSave = save;
            save.setOnLongClickListener(new android.view.View.OnLongClickListener() {
                public boolean onLongClick(android.view.View v) {
                    openCopyDialog();                    // segurar o APPLY: copiar para outros frames
                    return true;
                }
            });
            menu.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    switchKeepingText(TAB_MPT);         // volta ao painel completo, mesmo bloco em texto
                }
            });
            step.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    // >>: o jogo anda ate o proximo frame e a tela segue; o frame alterado e gravado antes de sair
                    autoSaveThen(new Runnable() {
                        public void run() {
                            followAfterStep = true;
                            frameStepRequests.addAndGet(1);
                        }
                    });
                }
            });
            redef.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    loadTab(true);                       // redefinir: volta ao arquivo (o jogo tambem volta)
                    setMsg("redefinido: igual ao arquivo", 0xFF9AA4B4);
                }
            });
            und.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    undoLast();
                }
            });
            boxes.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    showBoxes = !showBoxes;
                    boxes.setBackgroundColor(showBoxes ? 0xFF3A7BFF : 0xFF2A303C);
                    refreshLabels();
                }
            });
            save.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    saveOrRestart();
                }
            });
            refreshSaveButtons();

            TNode t = basicTree();
            if (!blockOk || t == null) {
                form.addView(label(a, blockOk ? "o texto deste MPT nao pode ser lido (use Menu / aba MPT)" : "sem MPT para editar", 10, 0xFFFF8080));
                return;
            }

            // sprite: [img - N +] [previa] [...]
            r = titledRow("SPR", 0xFF6AA1FF);
            if (t.kid("IMG") != null) {
                stepper(r, "", new Field(F_SCALAR, "IMG", 0, -1, 32767), 1f);
            } else {
                r.addView(label(a, "sem $IMG", 10, 0xFFFF8080), new android.widget.LinearLayout.LayoutParams(0, android.view.ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
            }
            thumb = new android.widget.ImageView(a);
            thumb.setBackgroundColor(0xFF161A21);
            thumb.setScaleType(android.widget.ImageView.ScaleType.FIT_CENTER);
            android.widget.LinearLayout.LayoutParams tl = new android.widget.LinearLayout.LayoutParams((int) (30 * d), (int) (30 * d));
            tl.setMargins((int) (2 * d), (int) d, (int) (2 * d), (int) d);
            r.addView(thumb, tl);
            android.widget.Button pick = miniButton(r, "…", 0);
            pick.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    pickSprite();
                }
            });

            // time: [time - N +] 0.13s   (ou botao para criar)
            r = titledRow("TIME", 0xFF6AA1FF);
            if (t.kid("TIME") != null) {
                stepper(r, "", new Field(F_SCALAR, "TIME", 0, 1, 255), 1f);
                timeSec = label(a, "", 10, 0xFFFFFFFF);
                timeSec.setGravity(android.view.Gravity.CENTER);
                timeSec.setMinWidth((int) (40 * d));
                r.addView(timeSec);
            } else {
                addButton(r, "+ $TIME", "TIME");
            }

            // x/y ($MID)
            r = titledRow("X/Y", 0xFF6AA1FF);
            TNode mid = t.kid("MID");
            if (mid != null && mid.ts.length >= 2) {
                stepper(r, "x", new Field(F_LIST, "MID", 0, -32768, 32767), 1);
                stepper(r, "y", new Field(F_LIST, "MID", 1, -32768, 32767), 1);
            } else {
                addButton(r, "+ $MID", "MID");
            }

            // caixas de hit (flag 2) e hurt (flag 1): 2 linhas por caixa
            TNode hits = t.kid("HITS");
            if (hits != null && hits.kids != null) {
                int nh = 0, nu = 0;
                for (int i = 0; i < hits.kids.size(); ++i) {
                    TNode h = hits.kids.get(i);
                    TNode fl = h.kid("FLAG");
                    TNode co = h.kid("COORDS");
                    if (fl == null || co == null || co.ts.length < 4) {
                        continue;
                    }
                    int flag = toInt(basicText.substring(fl.vs, fl.ve));
                    if (flag != 1 && flag != 2) {
                        continue;
                    }
                    String name = flag == 2 ? "HIT" + (++nh) : "HURT" + (++nu);
                    int col = flag == 2 ? 0xFFFF6A6A : 0xFF6AA8FF;
                    r = titledRow(name, col);
                    stepper(r, "x", new Field(F_HIT, h.key, 0, -32768, 32767), 1);
                    stepper(r, "y", new Field(F_HIT, h.key, 1, -32768, 32767), 1);
                    r = titledRow("", col);
                    stepper(r, "w", new Field(F_HIT, h.key, 2, 0, 32767), 1);
                    stepper(r, "h", new Field(F_HIT, h.key, 3, 0, 32767), 1);
                }
            }

            // raz (se existir)
            TNode raz = t.kid("RAZ");
            if (raz != null && raz.kids != null) {
                String[] keys = {"ROT", "ALPHA", "XZOOM", "YZOOM"};
                String[] names = {"rot", "alf", "xz", "yz"};
                r = null;
                int n = 0;
                for (int k = 0; k < 4; ++k) {
                    if (raz.kid(keys[k]) == null) {
                        continue;
                    }
                    if (n % 2 == 0) {
                        r = titledRow(n == 0 ? "RAZ" : "", 0xFF6AA1FF);
                    }
                    stepper(r, names[k], new Field(F_RAZ, keys[k], 0, -32768, 32767), 1);
                    n++;
                }
            }

            // som (se existir)
            if (t.kid("SE") != null) {
                r = titledRow("SE", 0xFF6AA1FF);
                stepper(r, "", new Field(F_SCALAR, "SE", 0, -128, 127), 1);
            }

            refreshForm();
        }

        static void addButton(android.view.ViewGroup parent, String text, final String what) {
            android.widget.Button b = miniButton(parent, text, 1);
            b.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    addField(what);
                }
            });
        }

        /** Escolher: a tela de SPRITES do app em modo escolha (tambem da para adicionar uma sprite nova). */
        static void pickSprite() {
            final String dir = curDir();
            android.app.Activity a = act();
            if (dir == null || a == null) {
                return;
            }
            Field img = null;
            for (int i = 0; i < fields.size(); ++i) {
                if (fields.get(i).kind == F_SCALAR && "IMG".equals(fields.get(i).key)) {
                    img = fields.get(i);
                }
            }
            if (img == null) {
                toast("este MPT nao tem $IMG");
                return;
            }
            if (isDirty() && !confirm()) {
                return;                          // grava antes: a tela de sprites pode regravar o .dac.txt
            }
            final Field fimg = img;
            Integer cur = getField(img);
            try {
                com.zue.attackeditor.GameEditBridge.pickSprite(a, new java.io.File(dir), curIsChar(), cur == null ? -1 : cur.intValue(),
                        new com.zue.attackeditor.GameEditBridge.Pick() {
                            public void onPick(int image) {
                                if (globalMode) {
                                    markReload(edSlot);         // sprite nova/trocada: o reiniciar recompila o pack
                                }
                                thumbImg = Integer.MIN_VALUE;   // a sprite pode ter sido trocada/adicionada agora
                                setField(fimg, image);
                            }
                        },
                        new com.zue.attackeditor.GameEditBridge.Frames() {
                            public void onFrames(int[] images, int[] delaysMs) {
                                if (images.length == 1) {
                                    thumbImg = Integer.MIN_VALUE;
                                    setField(fimg, images[0]);
                                } else {
                                    gifFrames(images, delaysMs);
                                }
                            }
                        });
            } catch (Throwable e) {
                android.util.Log.e(TAG, "escolher sprite", e);
                toast("erro: " + e.getMessage());
            }
        }

        // ---- GIF escolhido: o frame atual vira N frames (um por quadro do GIF) -----------------------

        /**
         * Ticks (60 por segundo) de cada quadro, arredondando pelo tempo acumulado para a soma bater com a
         * duracao real do GIF. Quadro com menos de 20 ms vale 100 ms (como os navegadores). Minimo 1, maximo 255.
         */
        static int[] gifTicks(int[] delaysMs) {
            int[] out = new int[delaysMs.length];
            long cum = 0;
            int used = 0;
            for (int i = 0; i < delaysMs.length; ++i) {
                int d = delaysMs[i] < 20 ? 100 : delaysMs[i];
                cum += d;
                int t = (int) Math.round(cum * 60.0 / 1000.0) - used;
                t = Math.max(1, Math.min(255, t));
                out[i] = t;
                used += t;
            }
            return out;
        }

        /** Copia do bloco $MPT com outro $IMG e $TIME (o resto igual). */
        static String withImgTime(String block, int img, int time) throws SynErr {
            TNode t = parseTree(block);
            TNode im = t.kid("IMG");
            TNode tm = t.kid("TIME");
            boolean imOk = im != null && im.kids == null && im.ts.length == 0;
            boolean tmOk = tm != null && tm.kids == null && tm.ts.length == 0;
            // trocas do fim para o comeco (as posicoes de antes continuam valendo)
            java.util.ArrayList<Object[]> ed = new java.util.ArrayList<Object[]>();
            if (imOk) {
                ed.add(new Object[]{Integer.valueOf(im.vs), Integer.valueOf(im.ve), String.valueOf(img)});
            }
            if (tmOk) {
                ed.add(new Object[]{Integer.valueOf(tm.vs), Integer.valueOf(tm.ve), String.valueOf(time)});
            } else if (imOk) {
                ed.add(new Object[]{Integer.valueOf(im.ks), Integer.valueOf(im.ks), "$TIME: " + time + ", "});
            }
            if (!imOk) {
                ed.add(new Object[]{Integer.valueOf(t.vs + 1), Integer.valueOf(t.vs + 1),
                        "\n   " + (tmOk ? "" : "$TIME: " + time + ", ") + "$IMG: " + img + ","});
            }
            java.util.Collections.sort(ed, new java.util.Comparator<Object[]>() {
                public int compare(Object[] x, Object[] y) {
                    return ((Integer) y[0]).compareTo((Integer) x[0]);
                }
            });
            for (int i = 0; i < ed.size(); ++i) {
                int s0 = ((Integer) ed.get(i)[0]).intValue(), s1 = ((Integer) ed.get(i)[1]).intValue();
                block = block.substring(0, s0) + ed.get(i)[2] + block.substring(s1);
            }
            return block;
        }

        /** $MPT_k -> $MPT_novo no comeco do bloco. */
        static String renameMpt(String block, int pat) throws SynErr {
            TNode t = parseTree(block);
            int ks = t.ks;
            int ke = ks + (block.charAt(ks) == '$' ? 1 : 0) + t.key.length();
            return block.substring(0, ks) + "$MPT_" + pat + block.substring(ke);
        }

        /**
         * No $ANO_ano do texto do .dac.txt, o $MPT_pat vira N frames seguidos (MPT_pat .. MPT_pat+N-1), copias
         * dele com o $IMG e o $TIME de cada quadro; os MPTs seguintes sao renumerados (+N-1).
         */
        static String gifExpand(String text, int ano, int pat, int[] images, int[] delaysMs) throws SynErr {
            int[] ab = findBlock(text, "ANO_" + ano, 0, text.length());
            if (ab == null) {
                throw new SynErr("$ANO_" + ano + " nao existe");
            }
            int[] mb = findBlock(text, "MPT_" + pat, ab[1] + 1, ab[2]);
            if (mb == null) {
                throw new SynErr("$MPT_" + pat + " nao existe no $ANO_" + ano);
            }
            int n = images.length;
            java.util.regex.Pattern key = java.util.regex.Pattern.compile("\\$MPT_(\\d+)(?=\\s*:)");
            int total = 0;
            java.util.regex.Matcher cm = key.matcher(text);
            cm.region(ab[1] + 1, ab[2]);
            while (cm.find()) {
                if (!inComment(text, cm.start())) {
                    total++;
                }
            }
            if (total + n - 1 > 255) {
                throw new SynErr("o ANO ficaria com " + (total + n - 1) + " frames (maximo 255)");
            }
            String ind = lineIndent(text, mb[0]);
            String block = deindent(text.substring(mb[0], mb[2] + 1), ind);
            parseTree(block);                    // confere antes de mexer
            int[] ticks = gifTicks(delaysMs);
            StringBuilder copies = new StringBuilder();
            for (int i = 0; i < n; ++i) {
                String c = renameMpt(withImgTime(block, images[i], ticks[i]), pat + i);
                if (i > 0) {
                    copies.append(",\n").append(ind);
                }
                copies.append(reindent(c, ind));
            }
            // renumera os MPTs depois deste, dentro do ANO
            String after = text.substring(mb[2] + 1, ab[2]);
            StringBuilder sb = new StringBuilder();
            java.util.regex.Matcher m = key.matcher(after);
            int last = 0;
            while (m.find()) {
                int k = Integer.parseInt(m.group(1));
                if (k <= pat || inComment(after, m.start())) {
                    continue;
                }
                sb.append(after, last, m.start()).append("$MPT_").append(k + n - 1);
                last = m.end();
            }
            sb.append(after.substring(last));
            return text.substring(0, mb[0]) + copies + sb + text.substring(ab[2]);
        }

        /** GIF escolhido no "…": grava o frame atual (se mudou), expande no .dac.txt e recarrega. */
        static void gifFrames(int[] images, int[] delaysMs) {
            if (isDirty() && !confirm()) {
                return;
            }
            String dir = curDir();
            if (dir == null || !blockOk) {
                return;
            }
            String path = fileOf(TAB_MPT, dir);
            int ano = edAno, pat = edPat, n = images.length;
            try {
                java.io.File f = new java.io.File(path);
                String text = readText(f);
                String out = gifExpand(text, ano, pat, images, delaysMs);
                java.io.File bak = new java.io.File(path + ".antes_editor");
                if (!bak.exists()) {
                    writeText(bak, text);
                }
                writeText(f, out);
                undo.add(new Object[]{path, Integer.valueOf(-1), Integer.valueOf(0), Integer.valueOf(ano), Integer.valueOf(pat), text});
                if (globalMode) {
                    markReload(edSlot);
                }
                thumbImg = Integer.MIN_VALUE;
                loadTab(false);
                savedJustNow = true;             // APPLY vira REINICIAR
                refreshSaveButtons();
                int ms = 0;
                for (int i = 0; i < delaysMs.length; ++i) {
                    ms += delaysMs[i] < 20 ? 100 : delaysMs[i];
                }
                String msg = "GIF: " + n + " frames (F " + pat + " a F " + (pat + n - 1) + ", " + ms + " ms) · reinicie para aplicar";
                setMsg(msg, 0xFF7CE08A);
                toast(msg);
            } catch (Exception e) {
                setMsg("GIF nao aplicado: " + e.getMessage(), 0xFFFF8080);
            }
        }

        /** Uma tela de sprites gravou (sprites e/ou .dac.txt): recarrega o bloco aberto se nao ha nada pendente. */
        static void onAssetsChanged() {
            if (globalMode) {
                markReload(edSlot);
            }
            thumbImg = Integer.MIN_VALUE;
            if (panelOpen && edLoaded && blockOk && !isDirty()) {
                loadTab(false);
                savedJustNow = true;             // mudancas nas sprites: APPLY vira REINICIAR
                refreshSaveButtons();
            }
        }

        // =====================================================================================
        // Modo ANOs (jogo todo): lista dos ANOs tocando -> basico (sprite, posicao, RAZ) -> Menu (texto)
        // =====================================================================================

        /** Botao ANOs: pausa o jogo e pede a lista dos ANOs tocando (montada na thread do jogo). */
        static void openGlobal() {
            if (root == null) {
                return;
            }
            android.widget.FrameLayout.LayoutParams lp = (android.widget.FrameLayout.LayoutParams) root.getLayoutParams();
            if (minimized) {
                setMinimized(false);
            }
            if (panel.getVisibility() != android.view.View.VISIBLE) {
                barLeft = lp.leftMargin;
                barTop = lp.topMargin;
            }
            if (!globalMode) {
                prevTab = tab;
            }
            expandedSlots.clear();               // os packs comecam fechados
            globalMode = true;
            globalEdit = false;
            tab = TAB_BASIC;
            blockOk = false;
            loadedText = "";
            basicText = "";
            savedJustNow = false;
            panel.setVisibility(android.view.View.VISIBLE);
            scrim.setVisibility(android.view.View.VISIBLE);
            paused = true;
            panelOpen = true;
            form.removeAllViews();
            fields.clear();
            thumb = null;
            timeSec = null;
            form.addView(label(act(), "lendo os ANOs que estao tocando...", 11, 0xFF9AA4B4));
            setMsg("", 0xFF9AA4B4);
            applyPanelLayout();
            globalListRequested = true;
            refreshLabels();
        }

        static void showGlobalList(java.util.ArrayList<GItem> list) {
            if (!panelOpen || !globalMode || globalEdit) {
                return;
            }
            lastList = list;
            renderGlobalList();
        }

        /** "+1F jogo": pede um tick (seguindo o ANO aberto, se houver). */
        static void requestGameTick() {
            if (gTickRequested || gTickRunning || gStepRequested || gStepping) {
                return;
            }
            gtFollow = globalEdit;
            gtSlot = edSlot;
            gtAct = edSlot >= 0 && edSlot < 31 ? CreatedAct[edSlot] : -1;
            gtAno = edAno;
            gtPat = edPat;
            gTickRequested = true;
        }

        /** Fim do "+1F jogo": lista nova; o ANO aberto segue o frame dele, ou volta para a lista se saiu da tela. */
        static void onGameTicked(java.util.ArrayList<GItem> list, boolean found, int pat) {
            if (!panelOpen || !globalMode) {
                return;
            }
            lastList = list;
            if (!globalEdit) {
                renderGlobalList();
                setMsg("+1 frame do jogo · " + list.size() + " ANO(s)", 0xFF9AA4B4);
                return;
            }
            if (!found) {
                toast("o ANO " + edAno + " nao esta mais na tela");
                gBoxes = false;
                renderGlobalList();
                return;
            }
            if (pat != edPat) {
                edPat = pat;
                loadTab(false);
            }
            setMsg("+1 frame do jogo · ANO " + edAno + " no F " + edPat, 0xFF9AA4B4);
        }

        /** Packs abertos na lista (por slot). Comecam todos fechados a cada vez que o ANOs abre. */
        static final java.util.HashSet<Integer> expandedSlots = new java.util.HashSet<Integer>();
        static final int GRID_COLS = 3;

        /**
         * Lista por pack:   select0 (2) ↓   [Sprites]
         *                   (aberto) grade de 3 por linha: miniatura da sprite atual + "Ano N" + "F n"
         */
        static void renderGlobalList() {
            final android.app.Activity a = act();
            if (a == null) {
                return;
            }
            final float d = dp();
            globalEdit = false;
            blockOk = false;
            loadedText = "";
            basicText = "";
            savedJustNow = false;
            form.removeAllViews();
            fields.clear();
            thumb = null;
            timeSec = null;
            thumbImg = Integer.MIN_VALUE;

            android.widget.LinearLayout r = row(a, form);
            android.widget.TextView h = label(a, "ANOs tocando agora", 12, 0xFFFFFFFF);
            h.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            h.setPadding((int) (3 * d), 0, 0, 0);
            r.addView(h, new android.widget.LinearLayout.LayoutParams(0, android.view.ViewGroup.LayoutParams.WRAP_CONTENT, 1f));
            android.widget.Button apk = miniButton(r, "APK", 0);
            apk.setBackgroundColor(0xFF1E5E2E);
            apk.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    openExportDialog();
                }
            });
            android.widget.Button again = miniButton(r, "\u21BB", 0);
            again.setOnClickListener(new android.view.View.OnClickListener() {
                public void onClick(android.view.View v) {
                    globalListRequested = true;
                }
            });

            if (lastList.isEmpty()) {
                form.addView(label(a, "nenhum ANO tocando (nenhum objeto com animacao na tela)", 10, 0xFFFFC060));
            }
            int i = 0;
            while (i < lastList.size()) {
                final GItem first = lastList.get(i);
                int j = i;
                while (j < lastList.size() && lastList.get(j).slot == first.slot) {
                    j++;
                }
                final int slot = first.slot;
                final boolean open = expandedSlots.contains(Integer.valueOf(slot));

                // cabecalho do pack
                android.widget.LinearLayout hr = row(a, form);
                ((android.widget.LinearLayout.LayoutParams) hr.getLayoutParams()).topMargin = (int) (3 * d);
                String title = (first.name == null ? "slot " + slot : first.name)
                        + (slot == 3 || slot == 4 ? " (P" + (slot - 2) + ")" : "")
                        + "  (" + (j - i) + ")  " + (open ? "\u2191" : "\u2193");
                android.widget.Button hb = miniButton(hr, title, 1);
                hb.setGravity(android.view.Gravity.LEFT | android.view.Gravity.CENTER_VERTICAL);
                hb.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
                hb.setPadding((int) (8 * d), (int) (6 * d), (int) (8 * d), (int) (6 * d));
                hb.setBackgroundColor(open ? 0xFF33405A : 0xFF2A303C);
                hb.setOnClickListener(new android.view.View.OnClickListener() {
                    public void onClick(android.view.View v) {
                        Integer k = Integer.valueOf(slot);
                        if (!expandedSlots.remove(k)) {
                            expandedSlots.add(k);
                        }
                        renderGlobalList();
                    }
                });
                android.widget.Button sb = miniButton(hr, "Sprites", 0);
                sb.setBackgroundColor(0xFF2B3F66);
                sb.setOnClickListener(new android.view.View.OnClickListener() {
                    public void onClick(android.view.View v) {
                        openPackSprites(first.dir, slot);
                    }
                });

                // grade (3 por linha)
                if (open) {
                    android.widget.LinearLayout gr = null;
                    for (int k = i; k < j; ++k) {
                        if ((k - i) % GRID_COLS == 0) {
                            gr = row(a, form);
                        }
                        gridCell(a, gr, lastList.get(k));
                    }
                    int rest = (j - i) % GRID_COLS;
                    for (int k = 0; rest != 0 && k < GRID_COLS - rest; ++k) {
                        android.view.View fill = new android.view.View(a);    // completa a ultima linha
                        gr.addView(fill, new android.widget.LinearLayout.LayoutParams(0, 1, 1f));
                    }
                }
                i = j;
            }
            setMsg(lastList.size() + " ANO(s) · toque no pack para abrir · voltar/tocar fora fecha", 0xFF9AA4B4);
            applyPanelLayout();
        }

        // ---- Mod APK (botao APK da lista do ANOs) ------------------------------------------------

        static final String APK_DIR = "/storage/emulated/0/Tap Battle/APK";
        static final String APK_TMP = "/storage/emulated/0/Tap Battle/Temp/mod_assets";

        static final String BASE_PKG = "com.namcobandaigames.dragonballtap.apk";
        /** Escolhas do menu APK (ficam lembradas enquanto o jogo esta aberto). */
        static String expName = "TapBattleMod";
        static String expPkg = BASE_PKG;
        static int expAndroid;                   // 0 = Android 14 ou menos (min 14 / target 29), 1 = Android 15+ (min 14 / target 30)
        static android.graphics.Bitmap expIcon;  // null = icone do base_apk
